pub fn run(config_path: PathBuf, state_dir: PathBuf, args: &[String]) -> AppResult<()> {
    if unsafe { libc::geteuid() } == 0 {
        return Err((
            1,
            "run mnode as your normal cluster account, without sudo; it prompts through the terminal when local or remote NFS administration needs sudo".into(),
        ));
    }
    if args.is_empty() || args.iter().any(|value| value == "-h" || value == "--help") {
        print_help(args.iter().any(|value| value == "--help"));
        return Ok(());
    }
    let action = parse_action(args)?;
    match action {
        Action::List { all, storage, node } => {
            list_nodes(&config_path, &state_dir, all, storage, node.as_ref())
        }
        Action::RepairNfs {
            node_id,
            assume_yes,
        } => crate::nfs_repair::repair_nfs_client(&config_path, &state_dir, &node_id, assume_yes),
        Action::Scan => {
            let config = read_config(&config_path)?;
            scan::scan_nodes(&config)
        }
        Action::Failures => list_failed_operations(&config_path, &state_dir),
        Action::Add(options) => add_node(&config_path, &state_dir, options),
        Action::AddCompute(node_id) => {
            mutate_compute_role(&config_path, &state_dir, &node_id, true)
        }
        Action::Mount { uri, options } => mount_storage(&config_path, &state_dir, uri, options),
        Action::MigrateController(node_id) => {
            migrate_controller(&config_path, &state_dir, &node_id)
        }
        Action::Remove {
            target,
            connect,
            force,
        } => {
            if let Some(share_id) = target.strip_prefix("share:") {
                remove_share(&config_path, &state_dir, share_id, force)
            } else {
                remove_node(&config_path, &state_dir, &target, connect.as_ref())
            }
        }
        Action::RemoveCompute(node_id) => {
            mutate_compute_role(&config_path, &state_dir, &node_id, false)
        }
        Action::Umount {
            target,
            force,
            assume_yes,
            wait,
            timeout,
        } => umount_storage(
            &config_path,
            &state_dir,
            target,
            force,
            assume_yes,
            wait,
            timeout,
        ),
    }
}

pub fn ensure_controller_recovery_clean(
    config_path: &Path,
    state_dir: &Path,
) -> Result<(), String> {
    let canonical = config_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve cluster config: {error}"))?;
    let path = state_dir.join("node-admin.json");
    if !path.exists() {
        return Ok(());
    }
    let state = read_admin_state(&path, &canonical, state_dir).map_err(|(_, error)| error)?;
    if let Some(operation) = state.operations.values().find(|operation| {
        matches!(
            operation.phase.as_str(),
            "ADD_COMMITTING" | "REMOVAL_COMMITTING" | "UPDATE_COMMITTING"
        )
    }) {
        let recovery_command = if operation.action == "update" {
            "rerun the command that triggered the Agent update"
        } else {
            "rerun its mnode command"
        };
        return Err(format!(
            "node operation {} for {} is at an uncertain config commit; {recovery_command} before starting the controller",
            operation.id, operation.node_id,
        ));
    }
    Ok(())
}

pub fn peer_config_sync_pending(config_path: &Path, state_dir: &Path) -> Result<bool, String> {
    let canonical = config_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve cluster config: {error}"))?;
    let journal_path = state_dir.join("node-admin.json");
    if !journal_path.exists() {
        return Ok(false);
    }
    let state =
        read_admin_state(&journal_path, &canonical, state_dir).map_err(|(_, error)| error)?;
    let source = fs::read(&canonical)
        .map_err(|error| format!("cannot read cluster config for sync barrier: {error}"))?;
    let digest = sha256_hex(&source).map_err(|error| error.to_string())?;
    Ok(state.operations.values().any(|operation| {
        operation.phase == "SYNC_PENDING"
            && operation.candidate_config_sha256.as_deref() == Some(digest.as_str())
    }))
}

pub(crate) fn has_committed_config_generation_path(
    config_path: &Path,
    state_dir: &Path,
    previous_config_digest: &str,
    active_config_digest: &str,
) -> Result<bool, String> {
    if previous_config_digest == active_config_digest {
        return Ok(false);
    }
    let canonical = config_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve cluster config: {error}"))?;
    let journal_path = state_dir.join("node-admin.json");
    if !journal_path.exists() {
        return Ok(false);
    }
    let state =
        read_admin_state(&journal_path, &canonical, state_dir).map_err(|(_, error)| error)?;
    let mut reachable_digests = BTreeSet::from([previous_config_digest.to_owned()]);
    loop {
        let before = reachable_digests.len();
        for operation in state.operations.values() {
            if !matches!(
                operation.phase.as_str(),
                "SYNC_PENDING" | "READY" | "REMOVED" | "REMOVED_OFFLINE"
            ) {
                continue;
            }
            let (Some(old), Some(candidate)) = (
                operation.old_config_sha256.as_deref(),
                operation.candidate_config_sha256.as_deref(),
            ) else {
                continue;
            };
            if reachable_digests.contains(old) {
                reachable_digests.insert(candidate.to_owned());
            }
        }
        if reachable_digests.contains(active_config_digest) {
            return Ok(true);
        }
        if reachable_digests.len() == before {
            return Ok(false);
        }
    }
}

pub(crate) fn agent_update_recovery_pending(
    config_path: &Path,
    state_dir: &Path,
) -> Result<bool, String> {
    let canonical = config_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve cluster config: {error}"))?;
    let journal_path = state_dir.join("node-admin.json");
    if !journal_path.exists() {
        return Ok(false);
    }
    let state =
        read_admin_state(&journal_path, &canonical, state_dir).map_err(|(_, error)| error)?;
    Ok(state.operations.values().any(|operation| {
        operation.action == "update"
            && !matches!(
                operation.phase.as_str(),
                "READY" | "REMOVED" | "REMOVED_OFFLINE" | "ABORTED"
            )
    }))
}

#[cfg(test)]
pub(crate) fn agent_helper_refresh_pending(state_dir: &Path) -> Result<bool, String> {
    let path = state_dir.join(HELPER_REFRESH_PENDING_FILE);
    let metadata = match fs::symlink_metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(false),
        Err(error) => return Err(format!("cannot inspect helper refresh marker: {error}")),
    };
    if !metadata.is_file()
        || metadata.file_type().is_symlink()
        || metadata.uid() != unsafe { libc::geteuid() }
        || metadata.permissions().mode() & 0o077 != 0
    {
        return Err(format!(
            "helper refresh marker {} has unsafe ownership or permissions",
            path.display()
        ));
    }
    Ok(true)
}

pub(crate) fn agent_helper_refresh_pending_nodes(
    state_dir: &Path,
    config: &ClusterConfig,
) -> Result<BTreeSet<String>, String> {
    let path = state_dir.join(HELPER_REFRESH_PENDING_FILE);
    let metadata = match fs::symlink_metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(BTreeSet::new()),
        Err(error) => return Err(format!("cannot inspect helper refresh marker: {error}")),
    };
    if !metadata.is_file()
        || metadata.file_type().is_symlink()
        || metadata.uid() != unsafe { libc::geteuid() }
        || metadata.permissions().mode() & 0o077 != 0
        || metadata.len() > 64 * 1024
    {
        return Err(format!(
            "helper refresh marker {} has unsafe ownership, permissions, type, or size",
            path.display()
        ));
    }
    let contents = fs::read_to_string(&path)
        .map_err(|error| format!("cannot read helper refresh marker: {error}"))?;
    if contents.trim() == "pending" {
        // Upgrade the old cluster-wide marker conservatively. New writes track
        // the specific Macs whose helper refresh still needs attention.
        return Ok(config
            .nodes
            .keys()
            .filter(|node_id| config.is_operational_node(node_id))
            .cloned()
            .collect());
    }
    let pending: AgentHelperRefreshPending = serde_json::from_str(&contents)
        .map_err(|error| format!("helper refresh marker is invalid: {error}"))?;
    if pending.schema != HELPER_REFRESH_PENDING_SCHEMA {
        return Err("helper refresh marker does not match the active node configuration".into());
    }
    Ok(pending
        .nodes
        .into_iter()
        .filter(|node_id| config.is_operational_node(node_id))
        .collect())
}

fn set_agent_helper_refresh_pending_nodes(state_dir: &Path, nodes: BTreeSet<String>) {
    let path = state_dir.join(HELPER_REFRESH_PENDING_FILE);
    if nodes.is_empty() {
        if let Err(error) = fs::remove_file(&path)
            && error.kind() != io::ErrorKind::NotFound
        {
            eprintln!("macluster: could not clear helper refresh marker: {error}");
        }
        return;
    }
    let pending = AgentHelperRefreshPending {
        schema: HELPER_REFRESH_PENDING_SCHEMA,
        nodes,
    };
    match serde_json::to_vec(&pending) {
        Ok(bytes) => {
            if let Err((_, error)) = atomic_write(&path, &bytes) {
                eprintln!("macluster: could not preserve pending helper refresh state: {error}");
            }
        }
        Err(error) => eprintln!("macluster: could not encode helper refresh state: {error}"),
    }
}

#[cfg(test)]
fn set_agent_helper_refresh_pending(state_dir: &Path, pending: bool) {
    let path = state_dir.join(HELPER_REFRESH_PENDING_FILE);
    if pending {
        if let Err((_, error)) = atomic_write(&path, b"pending\n") {
            eprintln!("macluster: could not preserve pending helper refresh state: {error}");
        }
    } else if let Err(error) = fs::remove_file(&path)
        && error.kind() != io::ErrorKind::NotFound
    {
        eprintln!("macluster: could not clear helper refresh marker: {error}");
    }
}

pub(crate) fn agent_update_blocked_by_work(state_dir: &Path) -> Result<bool, String> {
    if !state_dir.join("controller.sqlite3").is_file() {
        return Ok(false);
    }
    ReadOnlyJobStore::open(state_dir)
        .and_then(|store| store.has_maintenance_work())
        .map_err(|error| format!("cannot inspect active jobs or output synchronization: {error}"))
}

fn is_uncommitted_enrollment(config: &ClusterConfig, operation: &NodeOperation) -> bool {
    operation.action == "add"
        && matches!(
            operation.phase.as_str(),
            "SETUP_PENDING" | "CANDIDATE_INSTALLED"
        )
        && !config.nodes.contains_key(&operation.node_id)
}

fn is_uncommitted_named_share_setup(config: &ClusterConfig, operation: &NodeOperation) -> bool {
    if operation.action != "share" || operation.phase != "SETUP_PENDING" {
        return false;
    }
    parse_pending_named_share_endpoint(&operation.endpoint).is_ok_and(
        |(share_id, server_id, _, _, _)| {
            operation.node_id == server_id && !config.shares.contains_key(&share_id)
        },
    )
}

fn pending_share_has_no_remote_side_effects(operation: &NodeOperation) -> bool {
    operation.action == "share"
        && operation.phase == "SETUP_PENDING"
        && operation.client_setup_attempted == Some(false)
        && !operation.managed_export
        && operation.managed_shares.is_empty()
}

pub(crate) fn node_admin_recovery_pending(
    config_path: &Path,
    state_dir: &Path,
) -> Result<bool, String> {
    let canonical = config_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve cluster config: {error}"))?;
    let journal_path = state_dir.join("node-admin.json");
    if !journal_path.exists() {
        return Ok(false);
    }
    let state =
        read_admin_state(&journal_path, &canonical, state_dir).map_err(|(_, error)| error)?;
    let active_config = fs::read(&canonical)
        .map_err(|error| format!("cannot read active cluster config: {error}"))?;
    let active_digest = sha256_hex(&active_config).map_err(|error| error.to_string())?;
    // An uncommitted candidate is a private enrollment draft, not a cluster
    // member or a reason to fence updates to the active configuration.
    // An uncommitted named-share setup is isolated until its mapping is
    // committed. It remains visible in `mnode --failed` and can be resumed,
    // but it must not pause submissions or monitoring for the active cluster.
    // Invalid configs retain the conservative recovery behavior.
    let config = read_config(&canonical).ok();
    Ok(state.operations.values().any(|operation| {
        operation.action != "update"
            && !config
                .as_ref()
                .is_some_and(|config| is_uncommitted_enrollment(config, operation))
            && !config.as_ref().is_some_and(|config| {
                is_uncommitted_named_share_setup(config, operation)
                    && operation.old_config_sha256.as_deref() == Some(active_digest.as_str())
            })
            && !matches!(
                operation.phase.as_str(),
                "READY" | "REMOVED" | "REMOVED_OFFLINE" | "ABORTED"
            )
    }))
}

pub(crate) fn node_admin_blocks_agent_update(
    config_path: &Path,
    state_dir: &Path,
) -> Result<bool, String> {
    let canonical = config_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve cluster config: {error}"))?;
    let source =
        fs::read(&canonical).map_err(|error| format!("cannot read cluster config: {error}"))?;
    let digest = sha256_hex(&source).map_err(|error| error.to_string())?;
    let config = ClusterConfig::parse(
        std::str::from_utf8(&source)
            .map_err(|error| format!("cluster config is not UTF-8: {error}"))?,
    )
    .map_err(|error| error.to_string())?;
    let journal_path = state_dir.join("node-admin.json");
    if !journal_path.exists() {
        return Ok(false);
    }
    let state =
        read_admin_state(&journal_path, &canonical, state_dir).map_err(|(_, error)| error)?;
    let update_operation = state.operations.get("update:all");
    Ok(state.operations.values().any(|operation| {
        node_admin_operation_blocks_agent_update(&config, &digest, operation, update_operation)
    }))
}

fn node_admin_operation_blocks_agent_update(
    config: &ClusterConfig,
    config_digest: &str,
    operation: &NodeOperation,
    update_operation: Option<&NodeOperation>,
) -> bool {
    operation.action != "update"
        && !matches!(
            operation.phase.as_str(),
            "READY" | "REMOVED" | "REMOVED_OFFLINE" | "ABORTED"
        )
        && !is_uncommitted_enrollment(config, operation)
        && !is_superseded_local_enrollment_refresh(config, config_digest, operation)
        && !(is_uncommitted_named_share_setup(config, operation)
            && operation.old_config_sha256.as_deref() == Some(config_digest))
        && !can_resume_config_sync_during_agent_update(operation, config_digest, update_operation)
}

fn is_superseded_local_enrollment_refresh(
    config: &ClusterConfig,
    config_digest: &str,
    operation: &NodeOperation,
) -> bool {
    if operation.action != "add"
        || !matches!(
            operation.phase.as_str(),
            "SETUP_PENDING" | "CANDIDATE_INSTALLED"
        )
        || operation.old_config_sha256.as_deref() != Some(config_digest)
        || operation.candidate_config_sha256.is_some()
        || !operation.endpoint.starts_with("local@")
    {
        return false;
    }
    config.nodes.get(&operation.node_id).is_some_and(|node| {
        node.transport == Transport::Local
            && operation.machine_uuid.is_some()
            && node.machine_uuid.is_some()
            && operation.machine_uuid == node.machine_uuid
    })
}

fn retire_superseded_local_enrollment_refreshes(
    state: &mut AdminState,
    config: &ClusterConfig,
    config_digest: &str,
) -> usize {
    let mut retired = 0;
    for operation in state.operations.values_mut() {
        if !is_superseded_local_enrollment_refresh(config, config_digest, operation) {
            continue;
        }
        operation.phase = "ABORTED".into();
        operation.detail = Some(
            "superseded local node refresh was abandoned after the active config already contained the same local registration; existing mounts and shared data were preserved"
                .into(),
        );
        retired += 1;
    }
    retired
}

fn can_resume_config_sync_during_agent_update(
    operation: &NodeOperation,
    config_digest: &str,
    update_operation: Option<&NodeOperation>,
) -> bool {
    if operation.action == "update" || operation.phase != "SYNC_PENDING" {
        return false;
    }
    let Some(operation_candidate) = operation.candidate_config_sha256.as_deref() else {
        return false;
    };
    if operation_candidate == config_digest {
        return true;
    }
    update_operation.is_some_and(|update| {
        update.action == "update"
            && matches!(update.phase.as_str(), "UPDATE_COMMITTING" | "SYNC_PENDING")
            && update.candidate_config_sha256.as_deref() == Some(config_digest)
            && update.old_config_sha256.as_deref() == Some(operation_candidate)
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum UpdateRecovery {
    Fresh,
    Stage,
    Sync,
    AbandonUncommittedUpdate,
}

fn update_recovery(
    operation: Option<&NodeOperation>,
    current_digest: &str,
) -> Result<UpdateRecovery, String> {
    let Some(operation) = operation else {
        return Ok(UpdateRecovery::Fresh);
    };
    if operation.action != "update" {
        return Err("the all-node update journal entry has an unexpected action".into());
    }
    match operation.phase.as_str() {
        "READY" => Ok(UpdateRecovery::Fresh),
        "UPDATE_STAGING" | "UPDATE_FAILED"
            if operation.old_config_sha256.as_deref() == Some(current_digest) =>
        {
            Ok(UpdateRecovery::Stage)
        }
        "UPDATE_COMMITTING"
            if operation.candidate_config_sha256.as_deref() == Some(current_digest) =>
        {
            Ok(UpdateRecovery::Sync)
        }
        "UPDATE_COMMITTING" if operation.old_config_sha256.as_deref() == Some(current_digest) => {
            Ok(UpdateRecovery::Stage)
        }
        "SYNC_PENDING" if operation.candidate_config_sha256.as_deref() == Some(current_digest) => {
            Ok(UpdateRecovery::Sync)
        }
        "UPDATE_STAGING" | "UPDATE_FAILED"
            if operation.candidate_config_sha256.is_none()
                && operation.old_config_sha256.as_deref() != Some(current_digest) =>
        {
            // No candidate config was activated. A crash may leave the journal
            // in UPDATE_STAGING after an independent config change, so treat
            // that just like a failed pre-commit attempt: preserve its record
            // and unreferenced staged files, then stage from the active config
            // instead of blocking every Agent-dependent command.
            Ok(UpdateRecovery::AbandonUncommittedUpdate)
        }
        phase => Err(format!(
            "all-node update {} is in phase {phase}, but the active config matches neither its old nor candidate digest; inspect {} before retrying",
            operation.id, "node-admin.json"
        )),
    }
}

fn ensure_no_pending_admin_operation_for_config(
    state: &AdminState,
    config: &ClusterConfig,
    config_digest: &str,
) -> AppResult<()> {
    let update_operation = state.operations.get("update:all");
    let mut active = state.clone();
    active.operations.retain(|_, operation| {
        !is_uncommitted_enrollment(config, operation)
            && !is_superseded_local_enrollment_refresh(config, config_digest, operation)
            && !(is_uncommitted_named_share_setup(config, operation)
                && operation.old_config_sha256.as_deref() == Some(config_digest))
            && !can_resume_config_sync_during_agent_update(
                operation,
                config_digest,
                update_operation,
            )
    });
    ensure_no_pending_admin_operation(&active)
}

fn ensure_no_pending_admin_operation(state: &AdminState) -> AppResult<()> {
    for (key, operation) in &state.operations {
        if key == "update:all"
            || matches!(
                operation.phase.as_str(),
                "READY" | "REMOVED" | "REMOVED_OFFLINE" | "ABORTED"
            )
        {
            continue;
        }
        return Err((
            1,
            format!(
                "node admin operation {} for {} is still in phase {}; finish or resolve it with mnode before retrying the Agent update",
                operation.id, operation.node_id, operation.phase
            ),
        ));
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum AgentBuildState {
    Current,
    Stale,
    Unknown,
}

#[derive(Clone, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
pub(crate) struct AgentBuildCompatibility {
    pub(crate) current: Vec<String>,
    pub(crate) stale: Vec<String>,
    pub(crate) unknown: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub(crate) missing_required_features: Vec<String>,
}

impl AgentBuildCompatibility {
    pub(crate) fn requires_update(&self) -> bool {
        !self.stale.is_empty() || !self.missing_required_features.is_empty()
    }
}

struct AgentBuildProbe {
    version: String,
    sha256: Option<String>,
}

#[derive(Deserialize, Serialize)]
struct AgentValidationCache {
    schema: u32,
    key: String,
    checked_unix_ms: u64,
    compatibility: AgentBuildCompatibility,
}

const AGENT_VALIDATION_CACHE_TTL_MS: u64 = 60_000;
const AGENT_VALIDATION_CACHE_SCHEMA: u32 = 4;
const AGENT_VALIDATION_CACHE_MAX_BYTES: u64 = 64 * 1024;
const HELPER_REFRESH_PENDING_FILE: &str = "agent-helper-refresh.pending";
const HELPER_REFRESH_PENDING_SCHEMA: u32 = 1;

#[derive(Deserialize, Serialize)]
struct AgentHelperRefreshPending {
    schema: u32,
    nodes: BTreeSet<String>,
}

pub(crate) fn current_agent_sha256() -> AppResult<String> {
    let executable = std::env::current_exe().map_err(io_error)?;
    let executable = executable.canonicalize().map_err(io_error)?;
    local_sha256(&executable)
}

fn configured_agent_build_compatibility_excluding_offline(
    config: &ClusterConfig,
    confirmed_offline: &BTreeSet<String>,
) -> AppResult<AgentBuildCompatibility> {
    let current_digest = current_agent_sha256()?;
    let mut legacy_ssh = Vec::new();
    let mut compatibility = classify_configured_agents(config, |node_id, node| {
        if confirmed_offline.contains(node_id) {
            AgentBuildState::Unknown
        } else if node.transport == Transport::Ssh
            && managed_binary_digest(&node.remote_binary).is_none()
        {
            legacy_ssh.push((node_id.to_owned(), node.clone()));
            AgentBuildState::Unknown
        } else {
            inspect_configured_agent_build(node, &current_digest)
        }
    });

    // A legacy path has no digest in the config. Probe all such nodes in
    // parallel so one offline host does not delay a blocked submission by
    // one SSH timeout per queue member. Confirmed offline nodes are omitted;
    // their Unknown state is retried when liveness changes.
    let probed = bounded_legacy_agent_probes(legacy_ssh, &current_digest);
    for (node_id, state) in probed {
        compatibility.record(node_id, state);
    }
    compatibility.missing_required_features =
        bounded_agent_feature_probes(config, confirmed_offline);
    Ok(compatibility)
}

/// Probe only the SSH endpoints relevant to a pending update. This is a
/// bounded TCP check; it does not authenticate, start an Agent, or wait for an
/// SSH timeout on an unreachable node.
pub(crate) fn reachable_configured_node_ids(
    config: &ClusterConfig,
    candidates: &BTreeSet<String>,
) -> BTreeSet<String> {
    const WORKERS: usize = 32;
    let tasks = Mutex::new(VecDeque::from_iter(candidates.iter().filter_map(|id| {
        config
            .is_operational_node(id)
            .then(|| config.nodes.get(id).cloned().map(|node| (id.clone(), node)))
            .flatten()
    })));
    let workers = WORKERS.min(tasks.lock().map_or(0, |tasks| tasks.len()));
    std::thread::scope(|scope| {
        let handles = (0..workers)
            .map(|_| {
                let tasks = &tasks;
                scope.spawn(move || {
                    let mut reachable = Vec::new();
                    loop {
                        let Some((id, node)) =
                            tasks.lock().ok().and_then(|mut tasks| tasks.pop_front())
                        else {
                            break;
                        };
                        let online =
                            retry_endpoint_reachability(|| node_ssh_endpoint_reachable(&node));
                        if online {
                            reachable.push(id);
                        }
                    }
                    reachable
                })
            })
            .collect::<Vec<_>>();
        handles
            .into_iter()
            .flat_map(|handle| handle.join().unwrap_or_default())
            .collect()
    })
}

fn retry_endpoint_reachability(mut probe: impl FnMut() -> bool) -> bool {
    if probe() {
        return true;
    }
    // A single short TCP preflight can miss a node while its link or SSH
    // listener is recovering. Retry once before declaring it unavailable;
    // the parallel probe pool keeps this bounded for larger clusters.
    thread::sleep(Duration::from_millis(100));
    probe()
}

/// Check locally available build evidence without contacting any node.
pub(crate) fn configured_agent_build_mismatch_local(
    config: &ClusterConfig,
    cache_root: &Path,
) -> AppResult<bool> {
    let digest = current_agent_sha256()?;
    let receipts = AutoAgentUpdateReceipts::load_from_dir(cache_root).unwrap_or_default();
    Ok(config.nodes.iter().any(|(node_id, node)| {
        config.is_operational_node(node_id)
            && inspect_configured_agent_build(node, &digest) == AgentBuildState::Stale
            && !auto_agent_update_receipt_matches(&receipts, config, node_id, node)
    }))
}

pub(crate) fn configured_agent_build_compatibility_cached(
    config: &ClusterConfig,
    cache_root: &Path,
) -> AppResult<AgentBuildCompatibility> {
    configured_agent_build_compatibility_cached_with_age(config, cache_root)
        .map(|(compatibility, _)| compatibility)
}

pub(crate) fn configured_agent_build_compatibility_cached_with_age(
    config: &ClusterConfig,
    cache_root: &Path,
) -> AppResult<(AgentBuildCompatibility, u64)> {
    let confirmed_offline = configured_offline_probe_exclusions_from_cache(config, cache_root);
    let key = agent_validation_cache_key_with_offline(config, &confirmed_offline)?;
    let cache_path = cache_root.join("mtop-agent-validation.json");
    if let Some((mut cache, age_ms)) = read_agent_validation_cache(&cache_path, &key) {
        apply_auto_agent_update_receipts(config, cache_root, &mut cache);
        return Ok((cache, age_ms));
    }

    let mut compatibility =
        configured_agent_build_compatibility_excluding_offline(config, &confirmed_offline)?;
    apply_auto_agent_update_receipts(config, cache_root, &mut compatibility);
    let offline_after = configured_offline_probe_exclusions_from_cache(config, cache_root);
    if offline_after == confirmed_offline
        && agent_validation_cache_key_with_offline(config, &offline_after)
            .is_ok_and(|after| after == key)
    {
        write_agent_validation_cache(
            &cache_path,
            AgentValidationCache {
                schema: AGENT_VALIDATION_CACHE_SCHEMA,
                key,
                checked_unix_ms: validation_now_ms(),
                compatibility: compatibility.clone(),
            },
        );
    }
    Ok((compatibility, 0))
}

fn apply_auto_agent_update_receipts(
    config: &ClusterConfig,
    cache_root: &Path,
    compatibility: &mut AgentBuildCompatibility,
) {
    let Ok(receipts) = AutoAgentUpdateReceipts::load_from_dir(cache_root) else {
        return;
    };
    let updated = config
        .nodes
        .iter()
        .filter(|(node_id, node)| {
            compatibility.stale.iter().any(|stale| stale == *node_id)
                && auto_agent_update_receipt_matches(&receipts, config, node_id, node)
        })
        .map(|(node_id, _)| node_id.clone())
        .collect::<Vec<_>>();
    for node_id in updated {
        compatibility.stale.retain(|stale| stale != &node_id);
        compatibility
            .missing_required_features
            .retain(|missing| missing != &node_id);
        if !compatibility.current.contains(&node_id) {
            compatibility.current.push(node_id);
        }
    }
}

fn auto_agent_update_receipt_matches(
    receipts: &AutoAgentUpdateReceipts,
    config: &ClusterConfig,
    node_id: &str,
    node: &NodeConfig,
) -> bool {
    if node.transport != Transport::Ssh {
        return false;
    }
    let Some(entry) = receipts.nodes.get(node_id) else {
        return false;
    };
    let Ok(connection) = ConnectionKey::for_node(&config.share_uuid, node_id, node)
        .and_then(|key| key.cache_fingerprint())
    else {
        return false;
    };
    entry.remote_binary == node.remote_binary
        && node
            .machine_uuid
            .as_deref()
            .is_some_and(|uuid| uuid.eq_ignore_ascii_case(&entry.machine_uuid))
        && node.execution_uid == Some(entry.execution_uid)
        && entry.connection_fingerprint == connection
        && entry.build_id == macluster_protocol::BUILD_ID
}

fn bounded_legacy_agent_probes(
    nodes: Vec<(String, NodeConfig)>,
    current_digest: &str,
) -> Vec<(String, AgentBuildState)> {
    const MAX_PROBES: usize = 4;
    let queue = Mutex::new(VecDeque::from(nodes));
    let worker_count = MAX_PROBES.min(queue.lock().map_or(0, |queue| queue.len()));
    std::thread::scope(|scope| {
        let handles = (0..worker_count)
            .map(|_| {
                let queue = &queue;
                let current_digest = current_digest.to_owned();
                scope.spawn(move || {
                    let mut results = Vec::new();
                    loop {
                        let task = queue.lock().ok().and_then(|mut queue| queue.pop_front());
                        let Some((node_id, node)) = task else {
                            break;
                        };
                        let state = probe_configured_agent_build(&node, &current_digest);
                        results.push((node_id, state));
                    }
                    results
                })
            })
            .collect::<Vec<_>>();
        handles
            .into_iter()
            .filter_map(|handle| handle.join().ok())
            .flatten()
            .collect()
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AgentFeatureState {
    Current,
    Missing,
    Unknown,
}

fn missing_required_agent_features(features: &[String]) -> Vec<&'static str> {
    REQUIRED_AGENT_FEATURES
        .iter()
        .filter(|feature| !features.iter().any(|actual| actual == **feature))
        .copied()
        .collect()
}

fn probe_configured_agent_features(node: &NodeConfig) -> AgentFeatureState {
    let output = if node.transport == Transport::Local {
        let mut command = Command::new(&node.remote_binary);
        command.args(["internal", "capabilities", "--json"]);
        match run_child(command, None, Duration::from_secs(5)) {
            Ok(output) => output,
            Err(_) => return AgentFeatureState::Unknown,
        }
    } else {
        let command = shell_join(&[&node.remote_binary, "internal", "capabilities", "--json"]);
        match ssh_output(node, &command, None) {
            Ok(output) => output,
            Err(_) => return AgentFeatureState::Unknown,
        }
    };
    if !output.status.success() {
        return if node.transport == Transport::Ssh && output.status.code() == Some(255) {
            AgentFeatureState::Unknown
        } else {
            AgentFeatureState::Missing
        };
    }
    let Ok(report) = serde_json::from_slice::<CapabilityReport>(&output.stdout) else {
        return AgentFeatureState::Missing;
    };
    if report.build_id.as_deref() == Some(macluster_protocol::BUILD_ID)
        && missing_required_agent_features(&report.features).is_empty()
    {
        AgentFeatureState::Current
    } else {
        AgentFeatureState::Missing
    }
}

fn bounded_agent_feature_probes(
    config: &ClusterConfig,
    confirmed_offline: &BTreeSet<String>,
) -> Vec<String> {
    const MAX_PROBES: usize = 4;
    let queue = Mutex::new(
        config
            .nodes
            .iter()
            .filter(|(node_id, node)| {
                node.transport != Transport::Storage && !confirmed_offline.contains(*node_id)
            })
            .map(|(node_id, node)| (node_id.clone(), node.clone()))
            .collect::<VecDeque<_>>(),
    );
    let worker_count = MAX_PROBES.min(queue.lock().map_or(0, |queue| queue.len()));
    std::thread::scope(|scope| {
        let handles = (0..worker_count)
            .map(|_| {
                let queue = &queue;
                scope.spawn(move || {
                    let mut missing = Vec::new();
                    loop {
                        let task = queue.lock().ok().and_then(|mut queue| queue.pop_front());
                        let Some((node_id, node)) = task else {
                            break;
                        };
                        if probe_configured_agent_features(&node) == AgentFeatureState::Missing {
                            missing.push(node_id);
                        }
                    }
                    missing
                })
            })
            .collect::<Vec<_>>();
        handles
            .into_iter()
            .filter_map(|handle| handle.join().ok())
            .flatten()
            .collect()
    })
}

fn agent_validation_cache_key_with_offline(
    config: &ClusterConfig,
    confirmed_offline: &BTreeSet<String>,
) -> AppResult<String> {
    let executable = std::env::current_exe().map_err(io_error)?;
    let mut identity = format!(
        "schema={AGENT_VALIDATION_CACHE_SCHEMA};uid={};config={config:?};exe={}",
        unsafe { libc::geteuid() },
        file_identity_fingerprint(&executable)
    );
    for (node_id, node) in &config.nodes {
        if node.transport == Transport::Storage {
            continue;
        }
        if node.transport == Transport::Local {
            identity.push_str(&format!(
                ";local={node_id}:{}",
                file_identity_fingerprint(Path::new(&node.remote_binary))
            ));
        } else {
            let connection = ConnectionKey::for_node(&config.share_uuid, node_id, node)
                .map_err(|error| (1, error.to_string()))?;
            let digest = connection
                .cache_fingerprint()
                .map_err(|error| (1, error.to_string()))?;
            identity.push_str(&format!(";ssh={node_id}:{digest}"));
        }
    }
    for node_id in confirmed_offline {
        identity.push_str(&format!(";confirmed-offline={node_id}"));
    }
    sha256_hex(identity.as_bytes()).map_err(|error| (1, error.to_string()))
}

fn confirmed_offline_probe_exclusions(
    config: &ClusterConfig,
    records: &BTreeMap<String, macluster_controller::liveness::NodeLiveness>,
) -> BTreeSet<String> {
    config
        .nodes
        .iter()
        .filter_map(|(node_id, node)| {
            if node.transport != Transport::Ssh {
                return None;
            }
            let record = records.get(node_id)?;
            let expected_identity = node.machine_uuid.as_deref().unwrap_or(node.host.as_str());
            (record.identity_key.eq_ignore_ascii_case(expected_identity)
                && record.is_confirmed_offline())
            .then(|| node_id.clone())
        })
        .collect()
}

fn configured_offline_probe_exclusions_from_cache(
    config: &ClusterConfig,
    cache_root: &Path,
) -> BTreeSet<String> {
    let Some(state_dir) = cache_root.parent() else {
        return BTreeSet::new();
    };
    let Ok(records) = macluster_controller::liveness::read(state_dir, &config.share_uuid) else {
        return BTreeSet::new();
    };
    confirmed_offline_probe_exclusions(config, &records)
}

fn file_identity_fingerprint(path: &Path) -> String {
    let canonical = path.canonicalize().ok();
    let Some(canonical) = canonical else {
        return format!("{}:missing", path.display());
    };
    let Ok(metadata) = fs::metadata(&canonical) else {
        return format!("{}:missing", canonical.display());
    };
    format!(
        "{}:{}:{}:{}:{}:{}:{}:{}:{}",
        canonical.display(),
        metadata.dev(),
        metadata.ino(),
        metadata.len(),
        metadata.mtime(),
        metadata.mtime_nsec(),
        metadata.ctime(),
        metadata.ctime_nsec(),
        metadata.mode()
    )
}

fn read_agent_validation_cache(path: &Path, key: &str) -> Option<(AgentBuildCompatibility, u64)> {
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(path)
        .ok()?;
    let metadata = file.metadata().ok()?;
    if !metadata.is_file()
        || metadata.uid() != unsafe { libc::geteuid() }
        || metadata.permissions().mode() & 0o077 != 0
        || metadata.len() > AGENT_VALIDATION_CACHE_MAX_BYTES
    {
        return None;
    }
    let mut bytes = Vec::with_capacity(metadata.len() as usize);
    file.take(AGENT_VALIDATION_CACHE_MAX_BYTES + 1)
        .read_to_end(&mut bytes)
        .ok()?;
    if bytes.len() as u64 > AGENT_VALIDATION_CACHE_MAX_BYTES {
        return None;
    }
    let cache: AgentValidationCache = serde_json::from_slice(&bytes).ok()?;
    let age = validation_now_ms().checked_sub(cache.checked_unix_ms)?;
    (cache.schema == AGENT_VALIDATION_CACHE_SCHEMA
        && cache.key == key
        && age <= AGENT_VALIDATION_CACHE_TTL_MS)
        .then_some((cache.compatibility, age))
}

pub(crate) fn invalidate_agent_validation_cache(cache_root: &Path) {
    let _ = fs::remove_file(cache_root.join("mtop-agent-validation.json"));
}

fn write_agent_validation_cache(path: &Path, cache: AgentValidationCache) {
    let Some(parent) = path.parent() else {
        return;
    };
    if fs::create_dir_all(parent).is_err() {
        return;
    }
    let Ok(metadata) = fs::symlink_metadata(parent) else {
        return;
    };
    if !metadata.is_dir()
        || metadata.file_type().is_symlink()
        || metadata.uid() != unsafe { libc::geteuid() }
    {
        return;
    }
    if fs::set_permissions(parent, fs::Permissions::from_mode(0o700)).is_err() {
        return;
    }
    let temp_path = parent.join(format!(
        ".mtop-agent-validation-{}-{}.tmp",
        std::process::id(),
        validation_now_ms()
    ));
    let Ok(mut file) = OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .custom_flags(libc::O_NOFOLLOW)
        .open(&temp_path)
    else {
        return;
    };
    let result = serde_json::to_vec(&cache)
        .map_err(io::Error::other)
        .and_then(|bytes| file.write_all(&bytes))
        .and_then(|()| file.sync_all())
        .and_then(|()| fs::rename(&temp_path, path));
    if result.is_err() {
        let _ = fs::remove_file(temp_path);
    }
}

fn validation_now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

fn classify_configured_agents(
    config: &ClusterConfig,
    mut inspect: impl FnMut(&str, &NodeConfig) -> AgentBuildState,
) -> AgentBuildCompatibility {
    let mut compatibility = AgentBuildCompatibility::default();
    for (node_id, node) in &config.nodes {
        if node.transport == Transport::Storage {
            continue;
        }
        compatibility.record(node_id.clone(), inspect(node_id, node));
    }
    compatibility
}

impl AgentBuildCompatibility {
    fn record(&mut self, node_id: String, state: AgentBuildState) {
        match state {
            AgentBuildState::Current => self.current.push(node_id),
            AgentBuildState::Stale => self.stale.push(node_id),
            AgentBuildState::Unknown => self.unknown.push(node_id),
        }
    }
}

fn managed_binary_digest(binary: &str) -> Option<String> {
    let path = Path::new(binary);
    if path.file_name()? != "macluster" {
        return None;
    }
    let digest = path.parent()?.file_name()?.to_str()?;
    valid_sha256(digest).then(|| digest.to_ascii_lowercase())
}

fn is_expected_managed_agent_path(binary: &str, expected_digest: &str) -> bool {
    managed_binary_digest(binary).is_some_and(|digest| digest.eq_ignore_ascii_case(expected_digest))
}

fn valid_sha256(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn inspect_configured_agent_build(node: &NodeConfig, current_digest: &str) -> AgentBuildState {
    if node.transport == Transport::Local {
        return local_sha256(Path::new(&node.remote_binary))
            .map(|digest| compare_agent_digest(&digest, current_digest))
            .unwrap_or(AgentBuildState::Unknown);
    }
    let Some(digest) = managed_binary_digest(&node.remote_binary) else {
        return AgentBuildState::Unknown;
    };
    compare_agent_digest(&digest, current_digest)
}

fn compare_agent_digest(digest: &str, current_digest: &str) -> AgentBuildState {
    if digest.eq_ignore_ascii_case(current_digest) {
        AgentBuildState::Current
    } else {
        AgentBuildState::Stale
    }
}

fn probe_configured_agent_build(node: &NodeConfig, current_digest: &str) -> AgentBuildState {
    let binary = shell_quote(&node.remote_binary);
    let command = format!(
        "set -e; version=$({binary} --version); digest=$(/usr/bin/shasum -a 256 -- {binary}); digest=${{digest%% *}}; printf 'VERSION=%s\\nSHA256=%s\\n' \"$version\" \"$digest\""
    );
    let Ok(output) = ssh_output(node, &command, None) else {
        return AgentBuildState::Unknown;
    };
    if !output.status.success() {
        return AgentBuildState::Unknown;
    }
    let Some(probe) = parse_agent_build_probe(&String::from_utf8_lossy(&output.stdout)) else {
        return AgentBuildState::Unknown;
    };
    if let Some(digest) = probe.sha256 {
        return compare_agent_digest(&digest, current_digest);
    }
    let expected_version = format!("macluster {}", env!("CARGO_PKG_VERSION"));
    if probe.version.starts_with(&expected_version) {
        AgentBuildState::Current
    } else if probe.version.starts_with("macluster ") {
        AgentBuildState::Stale
    } else {
        AgentBuildState::Unknown
    }
}

fn parse_agent_build_probe(output: &str) -> Option<AgentBuildProbe> {
    let mut version = None;
    let mut sha256 = None;
    for line in output.lines() {
        if let Some(value) = line.strip_prefix("VERSION=") {
            version = Some(value.trim().to_owned());
        } else if let Some(value) = line.strip_prefix("SHA256=") {
            let value = value.trim();
            if valid_sha256(value) {
                sha256 = Some(value.to_ascii_lowercase());
            }
        }
    }
    let version = version.filter(|version| version.starts_with("macluster "))?;
    Some(AgentBuildProbe { version, sha256 })
}

fn verify_registered_node_identities(
    config: &ClusterConfig,
    nodes: &BTreeSet<String>,
) -> AppResult<()> {
    for (node_id, node) in &config.nodes {
        if !nodes.contains(node_id) || !config.is_operational_node(node_id) {
            continue;
        }
        let (machine_uuid, execution_uid) = if node.transport == Transport::Local {
            (local_platform_uuid()?, unsafe { libc::geteuid() })
        } else {
            let facts = read_remote_facts(node)
                .map_err(|(_, error)| (1, format!("cannot inspect node {node_id}: {error}")))?;
            let machine_uuid = remote_machine_uuid(node).map_err(|(_, error)| {
                (1, format!("cannot verify node {node_id} identity: {error}"))
            })?;
            (machine_uuid, facts.uid)
        };
        if node
            .machine_uuid
            .as_deref()
            .is_some_and(|expected| !expected.eq_ignore_ascii_case(&machine_uuid))
            || node
                .execution_uid
                .is_some_and(|expected| expected != execution_uid)
        {
            return Err((
                1,
                format!(
                    "node {node_id} no longer matches its registered machine UUID or execution UID: expected {}:{}, got {machine_uuid}:{execution_uid}",
                    node.machine_uuid.as_deref().unwrap_or("<unset>"),
                    node.execution_uid
                        .map(|uid| uid.to_string())
                        .unwrap_or_else(|| "<unset>".into())
                ),
            ));
        }
    }
    Ok(())
}

pub(crate) fn update_all_agents_for_preflight(
    config_path: &Path,
    state_dir: &Path,
    reachable_nodes: BTreeSet<String>,
) -> AppResult<bool> {
    update_all_agents_impl(config_path, state_dir, reachable_nodes)
}

fn agent_update_maintenance_scope(
    deferred_nodes: &BTreeSet<String>,
) -> AppResult<MaintenanceScope> {
    if deferred_nodes.is_empty() {
        return Ok(MaintenanceScope::Cluster);
    }
    let nodes = deferred_nodes
        .iter()
        .map(|node| {
            NodeId::new(node.clone()).map_err(|error| {
                (
                    2,
                    format!("invalid configured node ID '{node}' for update scope: {error}"),
                )
            })
        })
        .collect::<AppResult<Vec<_>>>()?;
    Ok(MaintenanceScope::ClusterExceptUnreachable(nodes))
}

pub(crate) fn hidden_node_notice(hidden: usize) -> Option<String> {
    (hidden > 0).then(|| {
        format!(
            "{hidden} unverified or unreachable compute node(s) hidden; use `mnode -l --all` to inspect them"
        )
    })
}

fn agent_update_completion_summary(prefix: &str, reachable: usize) -> String {
    let reachable_label = if reachable == 1 { "node" } else { "nodes" };
    format!("{prefix}: {reachable} reachable {reachable_label}.")
}

fn update_all_agents_impl(
    config_path: &Path,
    state_dir: &Path,
    preflight_reachable_nodes: BTreeSet<String>,
) -> AppResult<bool> {
    if unsafe { libc::geteuid() } == 0 {
        return Err((
            1,
            "run the Agent update as your normal cluster account, without sudo".into(),
        ));
    }
    let config_path = config_path.canonicalize().map_err(io_error)?;
    let initial_source = fs::read_to_string(&config_path).map_err(io_error)?;
    let initial_config =
        ClusterConfig::parse(&initial_source).map_err(|error| (2, error.to_string()))?;
    let initial_config_digest =
        sha256_hex(initial_source.as_bytes()).map_err(|error| (1, error.to_string()))?;
    let all_nodes = initial_config
        .nodes
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    let reachable_nodes = all_nodes
        .intersection(&preflight_reachable_nodes)
        .cloned()
        .collect::<BTreeSet<_>>();
    let deferred_nodes = all_nodes
        .difference(&reachable_nodes)
        .cloned()
        .collect::<BTreeSet<_>>();
    let maintenance_scope = agent_update_maintenance_scope(&deferred_nodes)?;
    let maintenance = acquire_node_maintenance_scoped(
        &config_path,
        state_dir,
        "Agent update",
        maintenance_scope,
    )?;
    if maintenance.recovered {
        return Ok(false);
    }
    let mut helper_refresh_deferred = None;
    let result = (|| -> AppResult<bool> {
        MaintenanceLock::bind_state_dir(&config_path, state_dir).map_err(|error| {
            (
                1,
                format!("cluster config/state directory binding failed: {error}"),
            )
        })?;
        fs::create_dir_all(state_dir).map_err(io_error)?;
        let source = fs::read_to_string(&config_path).map_err(io_error)?;
        if sha256_hex(source.as_bytes()).map_err(|error| (1, error.to_string()))?
            != initial_config_digest
        {
            return Err((
                1,
                "cluster config changed while checking node reachability; retry the Agent update"
                    .into(),
            ));
        }
        let config = ClusterConfig::parse(&source).map_err(|error| (2, error.to_string()))?;
        let old_digest = sha256_hex(source.as_bytes()).map_err(|error| (1, error.to_string()))?;
        let journal_path = state_dir.join("node-admin.json");
        let mut state = read_admin_state(&journal_path, &config_path, state_dir)?;
        if retire_superseded_local_enrollment_refreshes(&mut state, &config, &old_digest) > 0 {
            save_admin_state(&journal_path, &state)?;
        }
        ensure_no_pending_admin_operation_for_config(&state, &config, &old_digest)?;

        let operation_key = "update:all";
        let mut recovery = update_recovery(state.operations.get(operation_key), &old_digest)
            .map_err(|error| (1, error))?;
        if recovery == UpdateRecovery::AbandonUncommittedUpdate {
            let mut obsolete = state
                .operations
                .get(operation_key)
                .expect("superseded update recovery has an operation")
                .clone();
            obsolete.phase = "ABORTED".into();
            obsolete.detail = Some(
                "interrupted update had no committed candidate config and was superseded by a later cluster config change; unreferenced staging files were preserved".into(),
        );
            state.operations.insert(operation_key.to_owned(), obsolete);
            save_admin_state(&journal_path, &state)?;
            recovery = UpdateRecovery::Fresh;
        }
        if recovery == UpdateRecovery::Sync {
            let mut operation = state
                .operations
                .get(operation_key)
                .expect("sync recovery has an update operation")
                .clone();
            operation.phase = "SYNC_PENDING".into();
            operation.detail = None;
            state
                .operations
                .insert(operation_key.to_owned(), operation.clone());
            save_admin_state(&journal_path, &state)?;
            verify_registered_node_identities(&config, &reachable_nodes).map_err(
                |(code, error)| {
                    (
                        code,
                        format!("cannot verify node identities before Agent update: {error}"),
                    )
                },
            )?;
            let deferred = refresh_agent_helpers_for_update(
                &config,
                &operation.id,
                state_dir,
                &reachable_nodes,
            )?;
            set_agent_helper_refresh_pending_nodes(state_dir, deferred.clone());
            helper_refresh_deferred = Some(deferred);
            finish_update_sync(
                &mut state,
                &journal_path,
                operation_key,
                operation,
                &config,
                &source,
                state_dir,
            )?;
            println!(
                "{}",
                agent_update_completion_summary(
                    "Recovered Agent update sync",
                    reachable_nodes.len(),
                )
            );
            return Ok(maintenance.controller_was_running);
        }

        let mut operation = if recovery == UpdateRecovery::Stage {
            state
                .operations
                .get(operation_key)
                .expect("stage recovery has an update operation")
                .clone()
        } else {
            NodeOperation {
                id: Id128::random().to_string(),
                action: "update".into(),
                connection_endpoint: None,
                remote_config_path: None,
                node_id: "all".into(),
                endpoint: "cluster".into(),
                machine_uuid: None,
                phase: "UPDATE_STAGING".into(),
                old_config_sha256: Some(old_digest.clone()),
                candidate_config_sha256: None,
                managed_export: false,
                managed_shares: BTreeSet::new(),
                client_setup_attempted: Some(false),
                detail: None,
            }
        };
        operation.phase = "UPDATE_STAGING".into();
        operation.old_config_sha256 = Some(old_digest.clone());
        operation.candidate_config_sha256 = None;
        operation.detail = Some(format!(
            "staging and verifying the current Agent on {} reachable node(s)",
            reachable_nodes.len()
        ));
        state
            .operations
            .insert(operation_key.to_owned(), operation.clone());
        save_admin_state(&journal_path, &state)?;

        if let Err((code, error)) = verify_registered_node_identities(&config, &reachable_nodes) {
            operation.phase = "UPDATE_FAILED".into();
            operation.detail = Some(error.clone());
            state.operations.insert(operation_key.to_owned(), operation);
            save_admin_state(&journal_path, &state)?;
            return Err((
                code,
                format!(
                    "Agent update stopped because node identity verification failed: {error}. Correct the registered node identity, then rerun the requested command to resume the update."
                ),
            ));
        }

        let (candidate, candidate_config) = match stage_current_agents_for_nodes(
            &config,
            &source,
            &operation.id,
            AgentStagePurpose::Update,
            Some(&reachable_nodes),
        ) {
            Ok(candidate) => candidate,
            Err((code, error)) => {
                operation.phase = "UPDATE_FAILED".into();
                operation.detail = Some(error.clone());
                state.operations.insert(operation_key.to_owned(), operation);
                save_admin_state(&journal_path, &state)?;
                return Err((
                    code,
                    format!(
                        "Agent update stopped before config activation: {error}. Rerun the requested command to resume."
                    ),
                ));
            }
        };

        let current_source = fs::read(&config_path).map_err(io_error)?;
        let current_digest = sha256_hex(&current_source).map_err(|error| (1, error.to_string()))?;
        if current_digest != old_digest {
            operation.phase = "UPDATE_FAILED".into();
            operation.detail =
                Some("cluster config changed while Agent binaries were staged".into());
            state.operations.insert(operation_key.to_owned(), operation);
            save_admin_state(&journal_path, &state)?;
            return Err((
            1,
            "cluster config changed during Agent update; refusing to activate the staged paths. Inspect the node admin journal before retrying the requested command".into(),
        ));
        }

        operation.detail =
            Some("checking privileged helper versions and refreshing only changed services".into());
        state
            .operations
            .insert(operation_key.to_owned(), operation.clone());
        save_admin_state(&journal_path, &state)?;
        match refresh_agent_helpers_for_update(
            &candidate_config,
            &operation.id,
            state_dir,
            &reachable_nodes,
        ) {
            Ok(deferred) => {
                // Persist this before config activation/sync. If a later step
                // is interrupted, recovery must still know which offline
                // nodes have a helper refresh to perform when they return.
                set_agent_helper_refresh_pending_nodes(state_dir, deferred.clone());
                helper_refresh_deferred = Some(deferred);
            }
            Err((code, error)) => {
                operation.phase = "UPDATE_FAILED".into();
                operation.detail = Some(error.clone());
                state.operations.insert(operation_key.to_owned(), operation);
                save_admin_state(&journal_path, &state)?;
                return Err((
                    code,
                    format!(
                        "Agent binaries were staged, but privileged helper refresh failed before config activation: {error}. Rerun the requested command to resume."
                    ),
                ));
            }
        }

        let current_source = fs::read(&config_path).map_err(io_error)?;
        let current_digest = sha256_hex(&current_source).map_err(|error| (1, error.to_string()))?;
        if current_digest != old_digest {
            operation.phase = "UPDATE_FAILED".into();
            operation.detail =
                Some("cluster config changed while privileged helpers were refreshed".into());
            state.operations.insert(operation_key.to_owned(), operation);
            save_admin_state(&journal_path, &state)?;
            return Err((
                1,
                "cluster config changed during Agent helper refresh; refusing to activate staged paths. Inspect the node admin journal before retrying the requested command".into(),
            ));
        }

        let candidate_digest =
            sha256_hex(candidate.as_bytes()).map_err(|error| (1, error.to_string()))?;
        operation.candidate_config_sha256 = Some(candidate_digest.clone());
        if candidate == source {
            operation.phase = "SYNC_PENDING".into();
            operation.detail =
                Some("verifying peer config copies for the active Agent paths".into());
            state
                .operations
                .insert(operation_key.to_owned(), operation.clone());
            save_admin_state(&journal_path, &state)?;
            finish_update_sync(
                &mut state,
                &journal_path,
                operation_key,
                operation,
                &candidate_config,
                &candidate,
                state_dir,
            )?;
            println!(
                "{}",
                agent_update_completion_summary("Current Agent verified", reachable_nodes.len(),)
            );
            return Ok(maintenance.controller_was_running);
        }

        operation.phase = "UPDATE_COMMITTING".into();
        operation.detail = Some("activating verified Agent paths in the cluster config".into());
        state
            .operations
            .insert(operation_key.to_owned(), operation.clone());
        save_admin_state(&journal_path, &state)?;
        backup_config(&config_path, &operation.id)?;
        atomic_write(&config_path, candidate.as_bytes())?;
        operation.phase = "SYNC_PENDING".into();
        operation.detail = None;
        state
            .operations
            .insert(operation_key.to_owned(), operation.clone());
        save_admin_state(&journal_path, &state)?;
        finish_update_sync(
            &mut state,
            &journal_path,
            operation_key,
            operation,
            &candidate_config,
            &candidate,
            state_dir,
        )?;
        println!(
            "{}",
            agent_update_completion_summary("Agent update complete", reachable_nodes.len(),)
        );
        Ok(maintenance.controller_was_running)
    })();
    if result.is_ok()
        && let Some(deferred) = helper_refresh_deferred
    {
        set_agent_helper_refresh_pending_nodes(state_dir, deferred);
    }
    finish_node_maintenance_with_success_notice(maintenance, result, false)
}

fn finish_update_sync(
    state: &mut AdminState,
    journal_path: &Path,
    operation_key: &str,
    mut operation: NodeOperation,
    config: &ClusterConfig,
    source: &str,
    state_dir: &Path,
) -> AppResult<()> {
    // Keep private drafts anchored to this cluster when an Agent-only update
    // changes binary paths. Reset can still recognize and clean their exact
    // managed resources, and a later explicit add can reuse the draft.
    let current_digest = sha256_hex(source.as_bytes()).map_err(|error| (1, error.to_string()))?;
    if operation.candidate_config_sha256.as_deref() == Some(current_digest.as_str()) {
        let old_digest = operation.old_config_sha256.as_deref();
        let mut state_changed = false;
        for draft in state.operations.values_mut() {
            if (is_uncommitted_enrollment(config, draft)
                || is_uncommitted_named_share_setup(config, draft))
                && draft.old_config_sha256.as_deref() == old_digest
            {
                draft.old_config_sha256 = Some(current_digest.clone());
                state_changed = true;
            } else if draft.action != "update"
                && draft.phase == "SYNC_PENDING"
                && draft.candidate_config_sha256.as_deref() == old_digest
            {
                // This update will publish the new active config to every
                // configured peer. Rebase pending node/share config-sync
                // records before the remote sync, so an interrupted update
                // can safely resume it instead of being fenced by a stale
                // candidate digest.
                draft.candidate_config_sha256 = Some(current_digest.clone());
                state_changed = true;
            }
        }
        if state_changed {
            save_admin_state(journal_path, state)?;
        }
    }
    let all_nodes = config.nodes.keys().cloned().collect::<BTreeSet<_>>();
    let reachable_nodes = reachable_configured_node_ids(config, &all_nodes);
    if let Err(error) =
        sync_remote_configs_on_nodes(config, source, state_dir, &operation.id, &reachable_nodes)
    {
        operation.phase = "SYNC_PENDING".into();
        operation.detail = Some(error.clone());
        state.operations.insert(operation_key.to_owned(), operation);
        save_admin_state(journal_path, state)?;
        return Err((
            1,
            format!(
                "Agent paths are active locally, but peer config sync is pending: {error}. Rerun the requested command to resume the update."
            ),
        ));
    }
    for pending in state.operations.values_mut() {
        if pending.action == "update"
            || pending.phase != "SYNC_PENDING"
            || pending.candidate_config_sha256.as_deref() != Some(current_digest.as_str())
        {
            continue;
        }
        pending.phase = if pending.action == "remove" {
            "REMOVED".into()
        } else {
            "READY".into()
        };
        pending.detail = None;
    }
    operation.phase = "READY".into();
    operation.detail = None;
    state.operations.insert(operation_key.to_owned(), operation);
    save_admin_state(journal_path, state)?;
    Ok(())
}

fn parse_action(args: &[String]) -> AppResult<Action> {
    if args.is_empty() || args.iter().any(|value| value == "-h" || value == "--help") {
        print_help(args.iter().any(|value| value == "--help"));
        return Err((0, String::new()));
    }
    let (key, inline) = args[0]
        .split_once('=')
        .map_or((args[0].as_str(), None), |(key, value)| (key, Some(value)));
    if key == "--failed" {
        if args.len() != 1 || inline.is_some() {
            return Err((2, "mnode --failed does not accept a value".into()));
        }
        return Ok(Action::Failures);
    }
    if key == "-l" || key == "--list" {
        if inline.is_some() {
            return Err((2, "use `mnode -l [NODE_ID] [--all] [--storage]`".into()));
        }
        let mut all = false;
        let mut storage = false;
        let mut node = None;
        for option in &args[1..] {
            match option.as_str() {
                "--all" if !all => all = true,
                "--storage" if !storage => storage = true,
                "--all" | "--storage" => {
                    return Err((
                        2,
                        format!("mnode list option '{option}' may only appear once"),
                    ));
                }
                _ if option.starts_with('-') => {
                    return Err((2, "use `mnode -l [NODE_ID] [--all] [--storage]`".into()));
                }
                _ if node.is_none() => {
                    node =
                        Some(NodeId::new(option.clone()).map_err(|error| (2, error.to_string()))?);
                }
                _ => {
                    return Err((2, "mnode list accepts at most one node identifier".into()));
                }
            }
        }
        return Ok(Action::List { all, storage, node });
    }
    if key == "--repair-nfs" {
        let node_text = inline
            .map(str::to_owned)
            .or_else(|| args.get(1).cloned())
            .ok_or_else(|| (2, "mnode --repair-nfs requires NODE_ID".into()))?;
        let mut assume_yes = false;
        for option in &args[if inline.is_some() { 1 } else { 2 }..] {
            match option.as_str() {
                "--yes" if !assume_yes => assume_yes = true,
                "--yes" => return Err((2, "--yes may only be specified once".into())),
                _ => {
                    return Err((2, format!("unknown mnode --repair-nfs option '{option}'")));
                }
            }
        }
        return Ok(Action::RepairNfs {
            node_id: NodeId::new(node_text).map_err(|error| (2, error.to_string()))?,
            assume_yes,
        });
    }
    if key == "--scan" {
        if inline.is_some() || args.len() != 1 {
            return Err((2, "mnode --scan does not accept arguments".into()));
        }
        return Ok(Action::Scan);
    }
    if key == "-mount" || key == "--mount" {
        let uri_text = if let Some(value) = inline {
            value.to_owned()
        } else {
            args.get(1)
                .cloned()
                .ok_or_else(|| (2, format!("{key} requires a storage URI")))?
        };
        let (uri, inferred_host) = parse_cli_storage_uri(&uri_text)?;
        let mut mount_root = None;
        let mut overlay_existing = false;
        let mut server_host = None;
        let mut smb_user = None;
        let mut update_credential = false;
        let mut index = if inline.is_some() { 1 } else { 2 };
        while index < args.len() {
            match args[index].as_str() {
                "--overlay-existing" => {
                    if overlay_existing {
                        return Err((2, "--overlay-existing may only be specified once".into()));
                    }
                    overlay_existing = true;
                    index += 1;
                }
                "--update-credential" => {
                    if update_credential {
                        return Err((2, "--update-credential may only be specified once".into()));
                    }
                    update_credential = true;
                    index += 1;
                }
                "--mount-root" => {
                    if mount_root.is_some() {
                        return Err((2, "--mount-root may only be specified once".into()));
                    }
                    let value = args
                        .get(index + 1)
                        .ok_or_else(|| (2, "--mount-root requires an absolute path".into()))?
                        .trim_end_matches('/')
                        .to_owned();
                    if !safe_absolute_remote_path(&value) {
                        return Err((
                            2,
                            "--mount-root must be a normalized absolute path containing only ASCII letters, digits, '/', '.', '_' or '-'".into(),
                        ));
                    }
                    mount_root = Some(PathBuf::from(value));
                    index += 2;
                }
                "--host" => {
                    if server_host.is_some() {
                        return Err((2, "--host may only be specified once".into()));
                    }
                    let value = args
                        .get(index + 1)
                        .ok_or_else(|| (2, "--host requires an IPv4 address or DNS name".into()))?
                        .to_owned();
                    if !valid_storage_host(&value) {
                        return Err((2, "--host must be an IPv4 address or DNS name".into()));
                    }
                    server_host = Some(value);
                    index += 2;
                }
                "--smb-user" => {
                    if smb_user.is_some() {
                        return Err((2, "--smb-user may only be specified once".into()));
                    }
                    let value = args
                        .get(index + 1)
                        .ok_or_else(|| (2, "--smb-user requires an account name".into()))?
                        .clone();
                    if !valid_smb_user(&value) {
                        return Err((
                            2,
                            "SMB user is invalid; use letters, digits, '_', '.', or '-'".into(),
                        ));
                    }
                    smb_user = Some(value);
                    index += 2;
                }
                option => return Err((2, format!("unknown mnode mount option '{option}'"))),
            }
        }
        if let Some(inferred) = inferred_host {
            if let Some(explicit) = server_host.as_deref()
                && explicit != inferred
            {
                return Err((
                    2,
                    format!(
                        "--host {explicit} conflicts with the storage address {inferred} in {uri}"
                    ),
                ));
            }
            server_host.get_or_insert(inferred);
        }
        if uri.protocol != StorageProtocol::Smb && (smb_user.is_some() || update_credential) {
            return Err((
                2,
                "--smb-user and --update-credential are only valid for SMB storage URIs".into(),
            ));
        }
        return Ok(Action::Mount {
            uri,
            options: StorageMountOptions {
                mount_root: mount_root
                    .ok_or_else(|| (2, "mnode -mount requires --mount-root".into()))?,
                overlay_existing,
                server_host,
                smb_user,
                update_credential,
            },
        });
    }
    if key == "-umount" || key == "--umount" {
        let uri_text = inline
            .map(str::to_owned)
            .or_else(|| args.get(1).cloned())
            .ok_or_else(|| (2, format!("{key} requires a storage URI")))?;
        let mut force = false;
        let mut assume_yes = false;
        let mut wait = false;
        let mut timeout = None;
        let mut index = if inline.is_some() { 1 } else { 2 };
        while index < args.len() {
            match args[index].as_str() {
                "--force" if !force => {
                    force = true;
                    index += 1;
                }
                "--yes" if !assume_yes => {
                    assume_yes = true;
                    index += 1;
                }
                "--wait" if !wait => {
                    wait = true;
                    index += 1;
                }
                "--timeout" if timeout.is_none() => {
                    let value = args
                        .get(index + 1)
                        .ok_or_else(|| (2, "--timeout requires a value".into()))?;
                    timeout = Some(value.parse::<u64>().map_err(|_| {
                        (2, "--timeout must be an integer from 1 through 3600".into())
                    })?);
                    index += 2;
                }
                "--force" | "--yes" | "--wait" | "--timeout" => {
                    return Err((
                        2,
                        format!(
                            "mnode -umount option '{}' may only appear once",
                            args[index]
                        ),
                    ));
                }
                option => {
                    return Err((2, format!("unknown mnode -umount option '{option}'")));
                }
            }
        }
        if assume_yes && !force {
            return Err((2, "--yes is only valid with --force".into()));
        }
        if !wait && timeout.is_some() {
            return Err((2, "--timeout is only valid with --wait".into()));
        }
        if timeout.is_some_and(|seconds| !(1..=3600).contains(&seconds)) {
            return Err((2, "--timeout must be from 1 through 3600 seconds".into()));
        }
        let target = if uri_text.contains("://") {
            UmountTarget::Uri(parse_cli_storage_uri(&uri_text)?.0)
        } else {
            if !uri_text.bytes().enumerate().all(|(index, byte)| {
                if index == 0 {
                    byte.is_ascii_alphanumeric()
                } else {
                    byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-')
                }
            }) {
                return Err((2, format!("invalid storage mapping ID '{uri_text}'")));
            }
            UmountTarget::ShareId(uri_text)
        };
        return Ok(Action::Umount {
            target,
            force,
            assume_yes,
            wait,
            timeout,
        });
    }
    if key == "-migrate" || key == "--migrate" {
        if args.len() != (if inline.is_some() { 1 } else { 2 }) {
            return Err((2, format!("{key} requires controller:NODE_ID")));
        }
        let value = inline
            .map(str::to_owned)
            .or_else(|| args.get(1).cloned())
            .ok_or_else(|| (2, format!("{key} requires controller:NODE_ID")))?;
        let node_id = value
            .strip_prefix("controller:")
            .ok_or_else(|| (2, format!("{key} requires controller:NODE_ID")))?;
        return Ok(Action::MigrateController(
            NodeId::new(node_id.to_owned()).map_err(|error| (2, error.to_string()))?,
        ));
    }
    match key {
        "-a" | "--add" => {
            let endpoint = if let Some(value) = inline {
                value.to_owned()
            } else {
                args.get(1)
                    .cloned()
                    .ok_or_else(|| (2, format!("{key} requires an endpoint")))?
            };
            if let Some(node_id) = endpoint.strip_prefix("compute:") {
                if inline.is_some() || args.len() != 2 {
                    return Err((2, "compute role add accepts only compute:NODE_ID".into()));
                }
                return Ok(Action::AddCompute(
                    NodeId::new(node_id.to_owned()).map_err(|error| (2, error.to_string()))?,
                ));
            }
            if endpoint.starts_with("local:") {
                return Err((
                    2,
                    "mnode -a no longer creates additional NFS shares; add a share separately with `mnode -mount nfs://HOST/PATH --mount-root PATH`".into(),
                ));
            }
            if let Some(storage) = endpoint.strip_prefix("storage:") {
                if inline.is_some() || args.len() != 2 {
                    return Err((2, storage_provider_mount_help(None, None, None)));
                }
                let (node_id, host) = storage
                    .split_once('@')
                    .map_or((storage, None), |(node_id, host)| (node_id, Some(host)));
                return Err((
                    2,
                    storage_provider_mount_help(
                        Some(node_id),
                        host.filter(|host| !host.is_empty()),
                        None,
                    ),
                ));
            }
            let mut queue = None;
            let mut host = None;
            let mut index = if inline.is_some() { 1 } else { 2 };
            while index < args.len() {
                let option = args[index].as_str();
                if option == "--overlay-existing" {
                    return Err((
                        2,
                        "--overlay-existing applies to storage mounts; use it with `mnode -mount`, not `mnode -a`".into(),
                    ));
                }
                let value = args
                    .get(index + 1)
                    .cloned()
                    .ok_or_else(|| (2, format!("{option} requires a value")))?;
                match option {
                    "--queue" => {
                        QueueName::new(value.clone()).map_err(|error| (2, error.to_string()))?;
                        queue = Some(value);
                    }
                    "--share-id" => {
                        return Err((
                            2,
                            "NFS shares are managed separately from node registration; use `mnode -mount nfs://HOST/PATH --mount-root PATH`".into(),
                        ));
                    }
                    "--mount-root" => {
                        return Err((
                            2,
                            "--mount-root is a storage-mount option; use it with `mnode -mount`, not `mnode -a`".into(),
                        ));
                    }
                    "--host" => {
                        host = Some(
                            value
                                .parse::<Ipv4Addr>()
                                .map_err(|_| (2, "--host must be an IPv4 address".into()))?,
                        );
                    }
                    _ => return Err((2, format!("unknown mnode add option '{option}'"))),
                }
                index += 2;
            }
            let target = if let Some(local_source) = endpoint.strip_prefix("local") {
                if !local_source.is_empty() && !local_source.starts_with(':') {
                    return Err((
                        2,
                        "mnode -a accepts `local` without a path; add storage separately with `mnode -mount nfs://HOST/PATH --mount-root PATH`".into(),
                    ));
                }
                if !local_source.is_empty() {
                    return Err((
                        2,
                    "mnode -a no longer creates additional NFS shares; add a share separately with `mnode -mount nfs://HOST/PATH --mount-root PATH`".into(),
                    ));
                }
                AddTarget::Local {
                    source_path: None,
                    host,
                }
            } else {
                let parsed = NodeEndpoint::parse(&endpoint).map_err(|error| (2, error))?;
                if parsed.source_path.is_some() {
                    return Err((
                        2,
                        "mnode -a no longer creates additional NFS shares; add a share separately with `mnode -mount nfs://HOST/PATH --mount-root PATH`".into(),
                    ));
                }
                if parsed.host.is_loopback() {
                    let current_user = std::env::var("USER").unwrap_or_default();
                    if parsed.host != Ipv4Addr::LOCALHOST
                        || parsed.user != current_user
                        || parsed.port != 22
                    {
                        return Err((
                            2,
                            "only the current user at 127.0.0.1:22 may be registered as local"
                                .into(),
                        ));
                    }
                    AddTarget::Local {
                        source_path: None,
                        host,
                    }
                } else {
                    if host.is_some() {
                        return Err((2, "--host is only valid with mnode -a local".into()));
                    }
                    AddTarget::Ssh(parsed)
                }
            };
            Ok(Action::Add(AddOptions {
                target,
                queue,
                share_id: None,
                mount_root: None,
                overlay_existing: false,
            }))
        }
        "-rm" | "--remove" => {
            if inline.is_some() || args.len() < 2 {
                return Err((
                    2,
                    format!(
                        "{key} requires a node ID or pending share ID, optionally followed by --connect USER@IPv4[:PORT] or --force for a named share"
                    ),
                ));
            }
            let value = args[1].clone();
            if let Some(node_id) = value.strip_prefix("compute:") {
                if args.len() != 2 {
                    return Err((
                        2,
                        "compute role removal accepts only compute:NODE_ID".into(),
                    ));
                }
                return Ok(Action::RemoveCompute(
                    NodeId::new(node_id.to_owned()).map_err(|error| (2, error.to_string()))?,
                ));
            }
            let identifier = value.strip_prefix("share:").unwrap_or(&value);
            NodeId::new(identifier.to_owned()).map_err(|error| (2, error.to_string()))?;
            let is_share = value.starts_with("share:");
            let mut connect = None;
            let mut force = false;
            let mut index = 2;
            while index < args.len() {
                match args[index].as_str() {
                    "--force" if is_share => {
                        if force {
                            return Err((2, "--force may only be specified once".into()));
                        }
                        force = true;
                        index += 1;
                    }
                    "--force" => {
                        return Err((
                            2,
                            "--force is only supported when removing a named share".into(),
                        ));
                    }
                    "--connect" => {
                        if connect.is_some() {
                            return Err((2, "--connect may only be specified once".into()));
                        }
                        if is_share {
                            return Err((
                                2,
                                "--connect is only supported when removing a configured node"
                                    .into(),
                            ));
                        }
                        let endpoint = args
                            .get(index + 1)
                            .ok_or_else(|| (2, "--connect requires USER@IPv4[:PORT]".into()))?;
                        let endpoint = NodeEndpoint::parse(endpoint).map_err(|error| (2, error))?;
                        if endpoint.source_path.is_some() {
                            return Err((
                                2,
                                "--connect accepts USER@IPv4[:PORT], without a source path".into(),
                            ));
                        }
                        connect = Some(endpoint);
                        index += 2;
                    }
                    option => {
                        return Err((2, format!("unknown mnode remove option '{option}'")));
                    }
                }
            }
            if !is_share && force {
                return Err((
                    2,
                    "--force is only supported when removing a named share".into(),
                ));
            }
            if is_share && connect.is_some() {
                return Err((
                    2,
                    "--connect is only supported when removing a configured node".into(),
                ));
            }
            Ok(Action::Remove {
                target: value,
                connect,
                force,
            })
        }
        _ => Err((2, format!("unknown mnode option '{key}'"))),
    }
}

fn print_help(full: bool) {
    println!("{}", node_help(full));
}

fn node_help(full: bool) -> &'static str {
    if !full {
        return r#"Usage
  mnode -a|--add USER@IPv4[:PORT] [--queue QUEUE]
  mnode -a compute:NODE_ID
  mnode -mount URI --mount-root PATH [--host HOST]
  mnode -umount MAPPING_ID|SOURCE_URI|PENDING_SHARE_UUID [--force [--yes]] [--wait [--timeout SECONDS]]
  mnode -migrate controller:NODE_ID
  mnode --repair-nfs NODE_ID [--yes]
  mnode -l|--list [NODE_ID] [--all] [--storage]
  mnode -rm|--remove NODE_ID|compute:NODE_ID|share:SHARE_ID

OPTIONS
  --queue QUEUE       Choose a compute queue.
  --mount-root PATH   Required client mount path.
  --overlay-existing  Confirm covering existing files.
  --force             Force-detach a busy share.
  --yes               Confirm an unattended idle-node NFS reboot.
  --storage           Show detailed disk and share capacity.

EXAMPLES
  mnode -a user@192.0.2.10
  mnode -a compute:default-001
  mnode -mount smb://nas-user/data --mount-root /Volumes/data \
    --host 192.0.2.5 --smb-user nas-user
  mnode -mount nfs://login-01/Users/Shared/tools --mount-root /Users/Shared/tools
  mnode -umount mnt-0123456789abcdef
  mnode --repair-nfs default-001
  mnode -l --storage

Use `mnode -l --all` to include unreachable compute nodes.
"#;
    }

    r#"Usage
  mnode -a|--add USER@IPv4[:PORT] [--queue QUEUE]
  mnode -a compute:NODE_ID
  mnode -a local
  mnode -mount nfs://NODE/PATH --mount-root PATH [--host HOST] [--overlay-existing]
  mnode -mount smb://NODE/SHARE[/PATH] --mount-root PATH
        [--host HOST] [--smb-user ACCOUNT] [--update-credential] [--overlay-existing]
  mnode -umount MAPPING_ID|SOURCE_URI|PENDING_SHARE_UUID [--force [--yes]] [--wait [--timeout SECONDS]]
  mnode -migrate controller:NODE_ID
  mnode --repair-nfs NODE_ID [--yes]
  mnode -l|--list [NODE_ID] [--all] [--storage]
  mnode --scan
  mnode --failed
  mnode -rm|--remove NODE_ID [--connect USER@IPv4[:PORT]]
  mnode -rm compute:NODE_ID
  mnode -rm share:SHARE_ID [--force]

OPTIONS
  --queue QUEUE       Choose a compute queue.
  --host HOST         Select a login interface or external NAS IPv4/DNS name.
  --mount-root PATH   Choose a storage mapping's client mount path.
  --smb-user ACCOUNT  Choose the SMB account. The password is prompted once.
  --update-credential Replace the validated SMB password and fan it out.
  --overlay-existing  Confirm covering existing target files without a prompt.
                      Same-path NFS mounts ask for y/n confirmation when omitted.
  --connect USER@IP   Reach a moved node at its current address.
  --force             Force-detach a named share whose client mount is in use.
  --yes               Confirm an unattended idle-node NFS reboot.
  --wait              Wait for SMB mount cleanup after removal.
  --timeout SECONDS   Set the SMB cleanup wait limit (1..3600).
  --storage           Show per-node system, external and share capacity.

EXAMPLES
  mnode -a user@192.0.2.10
  mnode -a compute:default-001
  mnode -mount smb://nas-user/data --mount-root /Volumes/data \
    --host 192.0.2.5 --smb-user nas-user
  mnode -mount nfs://login-01/Users/Shared/tools --mount-root /Users/Shared/tools
  mnode -mount smb://nas-01/data/project --mount-root /Volumes/project \
    --smb-user smb-user
  mnode -umount mnt-0123456789abcdef
  mnode -umount smb://nas-01/data/project
  mnode -umount mnt-0123456789abcdef --force --yes
  mnode -umount mnt-0123456789abcdef --wait --timeout 60
  mnode --repair-nfs default-001
  mnode -a local
  mnode -mount nfs://192.0.2.10/opt/homebrew --mount-root /opt/homebrew
  mnode -rm default-001
  mnode -l --storage

`mnode -l` lists managed Macs; NAS/NFS/SMB providers appear only as storage
mappings. Default output uses cached capacity; `--storage` refreshes system,
external-volume and mounted share capacity in a bounded parallel pass.
Use `mnode -l NODE_ID` to show that Mac's host, SSH account, port and full
storage details.
Missed or inconclusive probes show `RECONNECTING` during the recovery grace;
three confirmed failures hide the node. Stale or unverified nodes stay hidden;
use `mnode -l --all` to inspect them.

NFS CLIENT RECOVERY
  `mnode --repair-nfs NODE_ID` actively probes configured NFS markers and
  offers to reboot an idle SSH compute node only when reads return the macOS
  client EINTR failure. It never reboots login, controller, or storage nodes.
  `--yes` skips the terminal prompt; it does not skip identity, wedge, idle,
  output-sync, or boot-ID safeguards.

ADD NODES
  Setup is verified before a node is listed. Failed attempts stay outside the
  list; inspect them with --failed and retry the original command. READY means
  the Agent, config, and shares are healthy; ONLINE means the Agent responds
  but checks are incomplete; OFFLINE means it does not respond.
  SSH Macs join the default compute queue unless --queue is set. If key login
  is not configured, mnode can install a dedicated SSH key after you verify
  the host fingerprint and enter the SSH account password once. Strict
  host-key verification remains enabled. Administrator authorization may be needed
  separately on each Mac. The configured login Mac stays outside compute queues.
  `mnode -a compute:NODE_ID` adds the compute capability to an existing node.
  `mnode -rm compute:NODE_ID` drains it before removing that capability.
  NAS and other external storage providers are not cluster nodes. Mount them
  directly with `mnode -mount` and provide `--host` when the URI uses a logical
  server ID. `mnode -umount` removes the mapping and its internal provider.

STORAGE MAPPINGS
  Node registration and extra storage mappings are separate operations.
  Use `mnode -mount nfs://SERVER/PATH --mount-root PATH` to add an NFS mapping;
  use `mnode -mount smb://SERVER/SHARE --mount-root PATH` for SMB. For a Mac
  already registered in the cluster, macluster manages its exact NFS exports.
  For an external NAS, the export must already be enabled on that device;
  macluster mounts and unmounts only on configured Macs and never changes NAS
  exports or writes markers into the provider's source directory.
  `mnode -umount MAPPING_ID` removes the mapping and its configured client
  mounts. Source data is preserved.

SMB CREDENTIALS
  The first new SMB server/account asks once with hidden input. The controller
  stores the validated master in its root-only credential vault and distributes
  a root-only node copy. The helper runs mount_smbfs in the target user context.
  Passwords never enter cluster config, SQLite, journals, job environment,
  command arguments, temporary files, or logs. Use --update-credential to
  validate and rotate a password before replacing the old master.
  Shares created before smb_user existed migrate in place by rerunning
  mnode -mount with the same URI and --mount-root plus --smb-user.
  Offline nodes receive the credential automatically before their SMB mounts
  are restored. Removing the last share for a server/account schedules cleanup.

REMOVE NODES
  `mnode -rm NODE_ID --connect USER@IPv4[:PORT]` reaches a moved node, verifies
  its machine UUID, and preserves the previous address for NFS export cleanup.
  The connection is saved for interrupted-removal retries. Host-key
  verification stays enabled. `mnode -rm share:SHARE_ID` removes a configured
  named share or cancels incomplete setup. If a client mount is in use, mnode
  lists the holding processes and asks before a forced detach; non-interactive
  callers can explicitly use --force. Forced unmount may make those processes
  fail with I/O errors. Source directories and files remain.

SCAN NETWORK
  `mnode --scan` searches only the subnet attached to the configured login
  address. It reports IP, MAC when known, SSH/RDP/AFP/ARD/SMB/NFS service
  availability, registered node ID, and a best-effort OS guess. Generic SSH
  banners may not identify macOS or Linux. Reachability checks do not verify
  login credentials and cannot enumerate authenticated SMB shares or NFS
  exports; use `mnode -l` for already configured source and target mappings.
  The interface link rate is shown when macOS reports it; this is not a
  throughput benchmark. Scanning is read-only; it does not enroll nodes or
  change SSH trust. Add a result separately with `mnode -a USER@IP`.

CONTROLLER MAINTENANCE
  Node, share, and controller-role changes pause submissions. Running jobs are
  not killed by ordinary maintenance. `mnode -migrate controller:NODE_ID`
  performs one interactive confirmation when active jobs or deferred helper
  work remains. Answer y to force-cancel active jobs, carry deferred offline
  Mac helper work to the new controller, and complete migration. Target
  identity, build, storage, credential, and controller-stop failures remain
  hard errors. The command moves the controller SQLite and activation state,
  fences the old controller, and restarts it automatically on failure."#
}

fn read_config(path: &Path) -> AppResult<ClusterConfig> {
    let source = fs::read_to_string(path)
        .map_err(|error| (1, format!("cannot read config {}: {error}", path.display())))?;
    ClusterConfig::parse(&source).map_err(|error| (2, error.to_string()))
}

fn read_admin_state(path: &Path, config_path: &Path, state_dir: &Path) -> AppResult<AdminState> {
    let config_identity =
        fs::canonicalize(config_path).unwrap_or_else(|_| config_path.to_path_buf());
    let state_identity = fs::canonicalize(state_dir).unwrap_or_else(|_| state_dir.to_path_buf());
    if path.exists() {
        let bytes = fs::read(path).map_err(io_error)?;
        let state: AdminState = serde_json::from_slice(&bytes).map_err(|error| {
            (
                1,
                format!("invalid node admin journal {}: {error}", path.display()),
            )
        })?;
        if state.version != 1
            || state.config_path != config_identity.to_string_lossy()
            || state.state_dir != state_identity.to_string_lossy()
        {
            return Err((
                1,
                "node admin journal belongs to a different config or state directory".into(),
            ));
        }
        Ok(state)
    } else {
        Ok(AdminState {
            version: 1,
            config_path: config_identity.to_string_lossy().into_owned(),
            state_dir: state_identity.to_string_lossy().into_owned(),
            reserved_node_ids: BTreeSet::new(),
            machine_uuids: BTreeMap::new(),
            operations: BTreeMap::new(),
        })
    }
}

fn save_admin_state(path: &Path, state: &AdminState) -> AppResult<()> {
    let bytes = serde_json::to_vec_pretty(state).map_err(|error| (1, error.to_string()))?;
    atomic_write(path, &bytes)
}

fn allocate_node_id(queue: &str, reserved: &BTreeSet<String>) -> AppResult<String> {
    if queue.len() + 4 > 64 {
        return Err((
            2,
            format!(
                "queue name '{queue}' is too long to form a node ID within the 64-character limit"
            ),
        ));
    }
    for index in 1..=999 {
        let candidate = format!("{queue}-{index:03}");
        if !reserved.contains(&candidate) {
            return Ok(candidate);
        }
    }
    Err((
        2,
        format!("no node IDs remain in queue '{queue}' (suffixes 001 through 999 are reserved)"),
    ))
}

fn config_path_candidate(
    config: &ClusterConfig,
    source: &str,
    node_id: &str,
    queue_name: &str,
    include_in_queue: bool,
    endpoint: &NodeEndpoint,
    remote_binary: &str,
    remote_config: &str,
    ssh_identity_file: Option<&str>,
    machine_uuid: &str,
    execution_uid: u32,
) -> AppResult<String> {
    let mut members = config
        .queues
        .get(queue_name)
        .ok_or_else(|| (2, format!("queue '{queue_name}' is not configured")))?
        .nodes
        .clone();
    if include_in_queue && !members.iter().any(|member| member == node_id) {
        members.push(node_id.to_owned());
    }
    let mut candidate = replace_queue_members(source, queue_name, &members)?;
    candidate.push_str("\n[nodes.");
    candidate.push_str(node_id);
    candidate.push_str("]\nhost = \"");
    candidate.push_str(&endpoint.host.to_string());
    candidate.push_str("\"\ntransport = \"ssh\"\nremote_binary = \"");
    candidate.push_str(remote_binary);
    candidate.push_str("\"\nssh_user = \"");
    candidate.push_str(&endpoint.user);
    candidate.push_str("\"\nssh_port = ");
    candidate.push_str(&endpoint.port.to_string());
    candidate.push_str("\nremote_config = \"");
    candidate.push_str(remote_config);
    candidate.push_str("\"\n");
    if let Some(identity_file) = ssh_identity_file {
        candidate.push_str("ssh_identity_file = ");
        candidate.push_str(&toml_quote(identity_file));
        candidate.push('\n');
    }
    candidate.push_str("machine_uuid = \"");
    candidate.push_str(machine_uuid);
    candidate.push_str("\"\nexecution_uid = ");
    candidate.push_str(&execution_uid.to_string());
    candidate.push('\n');
    ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
    Ok(candidate)
}

fn toml_quote(value: &str) -> String {
    let mut quoted = String::with_capacity(value.len() + 2);
    quoted.push('"');
    for character in value.chars() {
        match character {
            '\\' => quoted.push_str("\\\\"),
            '"' => quoted.push_str("\\\""),
            '\n' => quoted.push_str("\\n"),
            '\r' => quoted.push_str("\\r"),
            '\t' => quoted.push_str("\\t"),
            character => quoted.push(character),
        }
    }
    quoted.push('"');
    quoted
}

fn replace_queue_members(source: &str, queue: &str, members: &[String]) -> AppResult<String> {
    let section = format!("[queues.{queue}]");
    let mut lines: Vec<String> = source.lines().map(str::to_owned).collect();
    let start = lines
        .iter()
        .position(|line| line.trim() == section)
        .ok_or_else(|| (2, format!("config is missing {section}")))?;
    let end = lines[start + 1..]
        .iter()
        .position(|line| line.trim_start().starts_with('['))
        .map_or(lines.len(), |offset| start + 1 + offset);
    let key = (start + 1..end)
        .find(|index| {
            lines[*index]
                .split_once('=')
                .is_some_and(|(key, _)| key.trim() == "nodes")
        })
        .ok_or_else(|| (2, format!("{section} has no nodes array")))?;
    let value = members
        .iter()
        .map(|member| format!("\"{member}\""))
        .collect::<Vec<_>>()
        .join(", ");
    lines[key] = format!("nodes = [{value}]");
    Ok(lines.join("\n") + if source.ends_with('\n') { "\n" } else { "" })
}

fn queue_candidate_with_node(
    config: &ClusterConfig,
    source: &str,
    queue_name: &str,
    node_id: &str,
) -> AppResult<String> {
    if config.is_login_node(node_id) && !config.is_compute_node(node_id) {
        let mut candidate = source.to_owned();
        for (name, queue) in &config.queues {
            let members = queue
                .nodes
                .iter()
                .filter(|member| member.as_str() != node_id)
                .cloned()
                .collect::<Vec<_>>();
            candidate = replace_queue_members(&candidate, name, &members)?;
        }
        return Ok(candidate);
    }
    let mut members = config
        .queues
        .get(queue_name)
        .ok_or_else(|| (2, format!("queue '{queue_name}' is not configured")))?
        .nodes
        .clone();
    if !members.iter().any(|member| member == node_id) {
        members.push(node_id.to_owned());
    }
    replace_queue_members(source, queue_name, &members)
}

fn compute_role_candidate(
    config: &ClusterConfig,
    source: &str,
    node_id: &str,
    include: bool,
) -> AppResult<String> {
    if !config.nodes.contains_key(node_id) {
        return Err((2, format!("node '{node_id}' is not configured")));
    }
    let mut roles = config.node_roles(node_id);
    if include {
        roles.insert(macluster_core::config::NodeRole::Compute);
    } else {
        roles.remove(&macluster_core::config::NodeRole::Compute);
    }
    let mut candidate = source.to_owned();
    for (queue_name, queue) in &config.queues {
        let mut members = queue.nodes.clone();
        if include {
            if queue_name == config.default_queue.as_str()
                && !members.iter().any(|member| member == node_id)
            {
                members.push(node_id.to_owned());
            }
        } else {
            members.retain(|member| member != node_id);
        }
        candidate = replace_queue_members(&candidate, queue_name, &members)?;
    }
    let role_value = roles
        .iter()
        .map(|role| format!("\"{}\"", role.as_str()))
        .collect::<Vec<_>>()
        .join(", ");
    candidate = replace_section_key(
        &candidate,
        &format!("[nodes.{node_id}]"),
        "roles",
        &format!("[{role_value}]"),
    )?;
    let parsed = ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
    if parsed.is_compute_node(node_id) != include {
        return Err((
            1,
            format!("compute role update for {node_id} did not produce the requested role state"),
        ));
    }
    Ok(candidate)
}

fn controller_migration_idle_error(
    jobs: &[macluster_protocol::types::JobRecord],
) -> Option<String> {
    jobs.iter()
        .find(|job| {
            !job.state.is_terminal() || job.snapshot_sync_pending || job.log_sync_pending
        })
        .map(|job| {
            format!(
                "controller migration requires a completely idle cluster; job {} is {:?} and still blocks migration",
                job.id, job.state
            )
        })
}

fn controller_migration_post_stop_error(
    force_migration: bool,
    jobs: &[macluster_protocol::types::JobRecord],
) -> Option<String> {
    if force_migration {
        None
    } else {
        controller_migration_idle_error(jobs)
    }
}

fn controller_migration_job_blockers(jobs: &[macluster_protocol::types::JobRecord]) -> Vec<String> {
    jobs.iter()
        .filter_map(|job| {
            if !job.state.is_terminal() {
                Some(format!(
                    "active job {} is {:?} on {} and will be force-cancelled",
                    job.id,
                    job.state,
                    job.node.as_ref().map_or("-", NodeId::as_str)
                ))
            } else if job.snapshot_sync_pending || job.log_sync_pending {
                Some(format!(
                    "job {} has pending output synchronization and will be carried to the target controller",
                    job.id
                ))
            } else {
                None
            }
        })
        .collect()
}

fn controller_migration_maintenance_error(status: Option<&MaintenanceStatus>) -> Option<String> {
    status.map(|status| {
        format!(
            "controller migration requires no active maintenance; controller maintenance {} is {:?} for {:?}",
            status.ticket.operation_id, status.phase, status.scope
        )
    })
}

fn migration_jobs_to_cancel(jobs: &[macluster_protocol::types::JobRecord]) -> Vec<u64> {
    jobs.iter()
        .filter(|job| !job.state.is_terminal())
        .map(|job| job.id)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

fn confirm_force_controller_migration(blockers: &[String]) -> AppResult<()> {
    if !io::stdin().is_terminal() || !io::stderr().is_terminal() {
        return Err((
            2,
            format!(
                "controller migration has forceable blockers; rerun in Terminal to confirm: {}",
                blockers.join("; ")
            ),
        ));
    }
    eprintln!(
        "Controller migration will force-cancel active jobs and carry deferred work forward:"
    );
    for blocker in blockers {
        eprintln!("  - {blocker}");
    }
    eprint!(
        "Continue migration now? y force-cancels active jobs, carries deferred work forward, and completes migration. [y/N]: "
    );
    io::stderr().flush().map_err(io_error)?;
    let mut response = String::new();
    io::stdin().read_line(&mut response).map_err(io_error)?;
    if shutdown_confirmation_accepted(&response) {
        Ok(())
    } else {
        Err((
            1,
            "controller migration cancelled; no jobs or controller processes were stopped".into(),
        ))
    }
}

fn force_cancel_migration_jobs(
    binding: &ServiceBinding,
    state_dir: &Path,
    jobs: &[macluster_protocol::types::JobRecord],
) {
    let ids = migration_jobs_to_cancel(jobs);
    if ids.is_empty() {
        return;
    }
    eprintln!(
        "Force-cancelling active job(s): {}",
        ids.iter()
            .map(u64::to_string)
            .collect::<Vec<_>>()
            .join(", ")
    );
    match ControlClient::connect(binding, MAINTENANCE_CONTROL_TIMEOUT) {
        Ok(mut client) => {
            for job_id in &ids {
                if let Err(error) = client.request(ControlCommand::CancelJob {
                    job_id: *job_id,
                    force: true,
                }) {
                    eprintln!("Warning: job {job_id} cancellation request failed: {error}");
                }
            }
        }
        Err(error) => {
            eprintln!(
                "Warning: controller was not available to cancel job(s) {}: {error}",
                ids.iter()
                    .map(u64::to_string)
                    .collect::<Vec<_>>()
                    .join(", ")
            );
        }
    }
    let deadline = Instant::now() + Duration::from_secs(30);
    let mut last_notice = Instant::now();
    while Instant::now() < deadline {
        let remaining = ReadOnlyJobStore::open(state_dir)
            .ok()
            .and_then(|storage| storage.list_active_jobs().ok())
            .map(|jobs| migration_jobs_to_cancel(&jobs));
        match remaining {
            Some(remaining) if remaining.is_empty() => return,
            Some(remaining) if last_notice.elapsed() >= Duration::from_secs(3) => {
                eprintln!(
                    "Waiting for cancelled job(s) to stop: {}",
                    remaining
                        .iter()
                        .map(u64::to_string)
                        .collect::<Vec<_>>()
                        .join(", ")
                );
                last_notice = Instant::now();
            }
            Some(_) => {}
            None if last_notice.elapsed() >= Duration::from_secs(3) => {
                eprintln!("Waiting for the job database while cancelling migration blockers");
                last_notice = Instant::now();
            }
            None => {}
        }
        thread::sleep(Duration::from_millis(500));
    }
    eprintln!(
        "Warning: some jobs remain active after 30 seconds; the target controller will reconcile their cancellation state."
    );
}

fn controller_migration_candidate(
    config: &ClusterConfig,
    source: &str,
    target_id: &str,
    target_uid: u32,
) -> AppResult<String> {
    let target = config.nodes.get(target_id).cloned().ok_or_else(|| {
        (
            2,
            format!("controller target '{target_id}' is not configured"),
        )
    })?;
    let current_id = config
        .login_node
        .as_ref()
        .map(|node| node.as_str().to_owned())
        .or_else(|| {
            config
                .nodes
                .iter()
                .find(|(_, node)| node.transport == Transport::Local)
                .map(|(id, _)| id.clone())
        })
        .ok_or_else(|| (2, "configured controller node is missing".into()))?;
    if current_id == target_id {
        return Err((2, format!("node '{target_id}' is already the controller")));
    }
    if target.transport != Transport::Ssh {
        return Err((2, "controller target must be a registered SSH node".into()));
    }
    let old = config
        .nodes
        .get(&current_id)
        .expect("configured controller exists");
    let old_compute = config.is_compute_node(&current_id);
    let target_compute = config.is_compute_node(target_id);
    let user = std::env::var("USER")
        .ok()
        .filter(|user| !user.is_empty())
        .ok_or_else(|| (1, "USER is not set for controller migration".into()))?;
    let old_entry = format!(
        "[nodes.{current_id}]\nhost = \"{}\"\ntransport = \"ssh\"\nremote_binary = \"{}\"\nssh_user = \"{}\"\nssh_port = {}\nmachine_uuid = \"{}\"\nexecution_uid = {}\n{}\n",
        old.host,
        old.remote_binary,
        old.ssh_user.as_deref().unwrap_or(&user),
        old.ssh_port.unwrap_or(22),
        old.machine_uuid.as_deref().unwrap_or_default(),
        old.execution_uid.unwrap_or_default(),
        if old_compute {
            "roles = [\"compute\"]"
        } else {
            ""
        },
    );
    let target_entry = format!(
        "[nodes.{target_id}]\nhost = \"{}\"\ntransport = \"local\"\nremote_binary = \"{}\"\nmachine_uuid = \"{}\"\nexecution_uid = {}\n{}\n",
        target.host,
        target.remote_binary,
        target.machine_uuid.as_deref().unwrap_or_default(),
        target_uid,
        if target_compute {
            "roles = [\"compute\"]"
        } else {
            ""
        },
    );
    let mut candidate = replace_section_key(
        source,
        "[cluster]",
        "login_node",
        &format!("\"{target_id}\""),
    )?;
    for (queue_name, queue) in &config.queues {
        let old_was_member = queue.nodes.iter().any(|node| node == &current_id);
        let target_was_member = queue.nodes.iter().any(|node| node == &target_id);
        let mut members = queue
            .nodes
            .iter()
            .filter(|node| node.as_str() != current_id && node.as_str() != target_id)
            .cloned()
            .collect::<Vec<_>>();
        if old_compute && old_was_member {
            members.push(current_id.clone());
        }
        if target_compute && target_was_member {
            members.push(target_id.to_owned());
        }
        if queue_name == config.default_queue.as_str() {
            if old_compute && !members.iter().any(|node| node == &current_id) {
                members.push(current_id.clone());
            }
            if target_compute && !members.iter().any(|node| node == target_id) {
                members.push(target_id.to_owned());
            }
        }
        candidate = replace_queue_members(&candidate, queue_name, &members)?;
    }
    candidate = replace_or_append_table(&candidate, &format!("[nodes.{current_id}]"), &old_entry);
    candidate = replace_or_append_table(&candidate, &format!("[nodes.{target_id}]"), &target_entry);
    ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
    Ok(candidate)
}

fn controller_migration_primary_marker_check(shared_root: &Path, cluster_uuid: &str) -> String {
    let marker = shell_quote(&shared_root.join(".macluster-share-id").to_string_lossy());
    format!(
        "/bin/test -f {marker} && /bin/test ! -L {marker} && /usr/bin/grep -Fqx {} {marker}",
        shell_quote(cluster_uuid)
    )
}

fn controller_migration_target_preflight_script(
    shared_root: &Path,
    cluster_uuid: &str,
    target_config: &Path,
    target_state: &Path,
    remote_binary: &str,
) -> String {
    let marker_check = controller_migration_primary_marker_check(shared_root, cluster_uuid);
    let archive_root = target_state
        .parent()
        .unwrap_or_else(|| Path::new("."))
        .join("controller-archive");
    format!(
        "set -eu\n\
shared={shared}\n\
config={config}\n\
state={state}\n\
archive_root={archive_root}\n\
/bin/test -d \"$shared\" && {marker_check}\n\
digest=$(/usr/bin/shasum -a 256 {binary} | /usr/bin/awk '{{print $1}}')\n\
if /bin/test -e \"$config\" || /bin/test -e \"$state/controller.sqlite3\"; then\n\
  /bin/mkdir -p \"$archive_root\"\n\
  archive=\"$archive_root/migration-$(/bin/date +%s)-$$\"\n\
  /bin/mkdir -p \"$archive\"\n\
  if /bin/test -e \"$state/controller.sqlite3\"; then /bin/mv \"$state\" \"$archive/controller\"; fi\n\
  if /bin/test -e \"$config\"; then /bin/mv \"$config\" \"$archive/config.toml\"; fi\n\
  echo \"Archived stale target controller configuration and state at $archive\" >&2\n\
fi\n\
/bin/test ! -e \"$config\" && /bin/test ! -e \"$state/controller.sqlite3\" && /usr/bin/printf '%s\\n' \"$digest\"\n",
        shared = shell_quote(&shared_root.to_string_lossy()),
        config = shell_quote(&target_config.to_string_lossy()),
        state = shell_quote(&target_state.to_string_lossy()),
        archive_root = shell_quote(&archive_root.to_string_lossy()),
        binary = shell_quote(remote_binary),
    )
}

fn copy_controller_state_selection(source: &Path, destination: &Path) -> AppResult<()> {
    fs::create_dir_all(destination).map_err(io_error)?;
    for name in [
        "controller.sqlite3",
        "controller.sqlite3-wal",
        "controller.sqlite3-shm",
        "cluster-update.key",
        "cluster-update.sequence",
        "deferred-share-cleanup.json",
    ] {
        let from = source.join(name);
        if from.is_file() {
            fs::copy(&from, destination.join(name)).map_err(io_error)?;
        }
    }
    for name in ["client-networks", "snapshots", "client-submissions"] {
        let from = source.join(name);
        if from.is_dir() {
            copy_directory_private(&from, &destination.join(name))?;
        }
    }
    Ok(())
}

fn copy_directory_private(source: &Path, destination: &Path) -> AppResult<()> {
    fs::create_dir_all(destination).map_err(io_error)?;
    for entry in fs::read_dir(source).map_err(io_error)? {
        let entry = entry.map_err(io_error)?;
        let metadata = fs::symlink_metadata(entry.path()).map_err(io_error)?;
        let target = destination.join(entry.file_name());
        if metadata.file_type().is_symlink() {
            return Err((
                1,
                format!(
                    "controller migration encountered an unsupported symlink at {}",
                    entry.path().display()
                ),
            ));
        }
        if metadata.is_dir() {
            copy_directory_private(&entry.path(), &target)?;
        } else if metadata.is_file() {
            fs::copy(entry.path(), target).map_err(io_error)?;
        }
    }
    Ok(())
}

fn controller_migration_archive(config_source: &[u8], state_dir: &Path) -> AppResult<Vec<u8>> {
    let root = std::env::temp_dir().join(format!(
        "macluster-controller-migration-{}",
        Id128::random()
    ));
    fs::create_dir_all(&root).map_err(io_error)?;
    let result = (|| -> AppResult<Vec<u8>> {
        fs::write(root.join("config.toml"), config_source).map_err(io_error)?;
        copy_controller_state_selection(state_dir, &root.join("controller"))?;
        let archive = root.join("controller-migration.tar.gz");
        let status = Command::new("/usr/bin/tar")
            .args(["-czf"])
            .arg(&archive)
            .arg("-C")
            .arg(&root)
            .arg("config.toml")
            .arg("controller")
            .status()
            .map_err(io_error)?;
        if !status.success() {
            return Err((1, "controller migration archive creation failed".into()));
        }
        fs::read(&archive).map_err(io_error)
    })();
    let _ = fs::remove_dir_all(&root);
    result
}

fn controller_migration_target_script(
    target: &NodeConfig,
    target_home: &Path,
    operation_id: &str,
) -> String {
    let config_path = target_home.join(".config/macluster/config.toml");
    let state_dir = target_home.join("Library/Application Support/macluster/controller");
    let staging = target_home.join(format!(".macluster-controller-migration-{operation_id}"));
    format!(
        "set -eu\nconfig={config}\nstate={state}\nstaging={staging}\nif [ -e \"$config\" ] || [ -e \"$state/controller.sqlite3\" ]; then echo 'target already has active controller configuration or state' >&2; exit 9; fi\n/bin/rm -rf \"$staging\"\n/bin/mkdir -p \"$staging\"\n/usr/bin/tar -xzf - -C \"$staging\"\n/bin/mkdir -p \"$(/usr/bin/dirname \"$config\")\" \"$state\"\n/bin/cp \"$staging/config.toml\" \"$config\"\n/bin/cp -R \"$staging/controller/.\" \"$state/\"\n{bin} --config \"$config\" --state-dir \"$state\" controller start\n{bin} --config \"$config\" --state-dir \"$state\" internal sync-peer-config\n{bin} --config \"$config\" --state-dir \"$state\" controller restart\n{bin} --config \"$config\" --state-dir \"$state\" mnode -l >/dev/null\n/bin/rm -rf \"$staging\"\n",
        config = shell_quote(&config_path.to_string_lossy()),
        state = shell_quote(&state_dir.to_string_lossy()),
        staging = shell_quote(&staging.to_string_lossy()),
        bin = shell_quote(&target.remote_binary),
    )
}

fn run_controller_migration_target_command(
    target: &NodeConfig,
    script: &str,
    input: Option<&[u8]>,
    timeout: Duration,
) -> Result<Output, String> {
    ssh_output_with_timeout(target, script, input, timeout).map_err(|(_, error)| error)
}

fn stage_controller_migration_target_binary(target: &NodeConfig) -> AppResult<()> {
    let source = std::env::current_exe().map_err(io_error)?;
    let source = source.canonicalize().map_err(io_error)?;
    let staging = format!(
        "{}.macluster-stage-{}",
        target.remote_binary,
        Id128::random()
    );
    scp_to_node(target, &source, &staging)?;
    let install = format!(
        "/bin/chmod 700 {} && /bin/mv -f {} {}",
        shell_quote(&staging),
        shell_quote(&staging),
        shell_quote(&target.remote_binary),
    );
    remote_run(target, &install, None)?;
    Ok(())
}

fn controller_migration_target_cleanup_script(
    target: &NodeConfig,
    target_home: &Path,
    operation_id: &str,
) -> String {
    let config_path = target_home.join(".config/macluster/config.toml");
    let state_dir = target_home.join("Library/Application Support/macluster/controller");
    let staging = target_home.join(format!(".macluster-controller-migration-{operation_id}"));
    format!(
        "set -eu\nconfig={config}\nstate={state}\nstaging={staging}\nif [ -f \"$config\" ]; then {bin} --config \"$config\" --state-dir \"$state\" controller stop >/dev/null; fi\n/bin/rm -f \"$config\"\n/bin/rm -rf \"$state\" \"$staging\"\n/bin/test ! -e \"$config\"\n/bin/test ! -e \"$state/controller.sqlite3\"\n",
        config = shell_quote(&config_path.to_string_lossy()),
        state = shell_quote(&state_dir.to_string_lossy()),
        staging = shell_quote(&staging.to_string_lossy()),
        bin = shell_quote(&target.remote_binary),
    )
}

fn run_target_smb_master_command(
    target: &NodeConfig,
    operation: &str,
    provision: &macluster_protocol::smb_credential::SmbCredentialProvision,
    include_password: bool,
) -> Result<(), String> {
    let mut parts = vec![target.remote_binary.clone()];
    if let Some(config) = &target.remote_config {
        parts.push("--config".into());
        parts.push(config.clone());
    }
    parts.extend([
        "internal".into(),
        "smb-master".into(),
        operation.into(),
        "--cluster-uuid".into(),
        provision.key.cluster_uuid.to_string(),
        "--server-id".into(),
        provision.key.server_id.to_string(),
        "--server".into(),
        provision.key.server_host.clone(),
        "--account".into(),
        provision.key.account.clone(),
    ]);
    if include_password {
        parts.push("--generation".into());
        parts.push(provision.credential.generation.to_string());
    }
    let command = parts
        .iter()
        .map(|argument| shell_quote(argument))
        .collect::<Vec<_>>()
        .join(" ");
    let input = include_password.then(|| provision.credential.password.as_secret().as_bytes());
    let output =
        run_controller_migration_target_command(target, &command, input, Duration::from_secs(45))?;
    if output.status.success() {
        Ok(())
    } else {
        Err(format!(
            "target SMB master {operation} exited with status {:?}",
            output.status.code()
        ))
    }
}

fn cleanup_target_smb_masters(
    target: &NodeConfig,
    provisions: &[macluster_protocol::smb_credential::SmbCredentialProvision],
) {
    cleanup_target_smb_masters_with(provisions, |provision| {
        let _ = run_target_smb_master_command(target, "delete", provision, false);
    });
}

fn cleanup_target_smb_masters_with(
    provisions: &[macluster_protocol::smb_credential::SmbCredentialProvision],
    mut cleanup: impl FnMut(&macluster_protocol::smb_credential::SmbCredentialProvision),
) {
    for provision in provisions {
        cleanup(provision);
    }
}

fn stage_target_smb_masters(
    provisions: &[macluster_protocol::smb_credential::SmbCredentialProvision],
    mut import: impl FnMut(
        &macluster_protocol::smb_credential::SmbCredentialProvision,
    ) -> Result<(), String>,
    mut verify: impl FnMut(
        &macluster_protocol::smb_credential::SmbCredentialProvision,
    ) -> Result<(), String>,
    mut cleanup: impl FnMut(&macluster_protocol::smb_credential::SmbCredentialProvision),
) -> Result<(), String> {
    let mut imported = Vec::new();
    for provision in provisions {
        if let Err(error) = import(provision) {
            cleanup(provision);
            for imported in &imported {
                cleanup(imported);
            }
            return Err(error);
        }
        imported.push(provision.clone());
    }
    for provision in &imported {
        if let Err(error) = verify(provision) {
            for imported in &imported {
                cleanup(imported);
            }
            return Err(error);
        }
    }
    Ok(())
}

fn controller_migration_may_restart_old(was_running: bool, target_cleanup_ok: bool) -> bool {
    was_running && target_cleanup_ok
}

fn controller_migration_peer_sync_error_is_local_only(
    error: &str,
    local_node_id: Option<&str>,
) -> bool {
    local_node_id.is_some_and(|node_id| {
        !error.contains("; ")
            && error.contains(&format!("remote config sync is pending on {node_id}:"))
    })
}

fn controller_migration_join_endpoint(target: &NodeConfig) -> Result<String, String> {
    let user = target
        .ssh_user
        .as_deref()
        .filter(|user| !user.is_empty())
        .ok_or_else(|| "controller target has no SSH user for automatic client join".to_owned())?;
    Ok(format!(
        "{user}@{}:{}",
        target.host,
        target.ssh_port.unwrap_or(22)
    ))
}

fn controller_migration_auto_join_with(
    target: &NodeConfig,
    cluster_uuid: &str,
    join: impl FnOnce(&str, bool, Option<&str>) -> Result<(), String>,
) -> Result<(), String> {
    let endpoint = controller_migration_join_endpoint(target)?;
    join(&endpoint, true, Some(cluster_uuid))
}

fn controller_migration_auto_join(target: &NodeConfig, cluster_uuid: &str) -> Result<(), String> {
    controller_migration_auto_join_with(
        target,
        cluster_uuid,
        |endpoint, control_only, expected_cluster_uuid| {
            crate::client_join::join_cluster_expected_with_binary(
                endpoint,
                control_only,
                expected_cluster_uuid,
                Some(&target.remote_binary),
                true,
                true,
            )
            .map(|_| ())
        },
    )
}

fn migrate_controller(config_path: &Path, state_dir: &Path, target_id: &NodeId) -> AppResult<()> {
    let config_path = config_path.canonicalize().map_err(io_error)?;
    let config = read_config(&config_path)?;
    let (migration_config, recovered_smb_users, mut preflight_warnings) =
        recover_missing_smb_users(&config);
    let smb_masters = match macluster_controller::smb_credential::export_smb_masters(
        &migration_config,
        &macluster_controller::smb_credential::CredentialHelperClient::system(),
    ) {
        Ok(masters) => masters,
        Err(error) => {
            preflight_warnings.push(format!(
                "SMB master credentials will not be migrated: {error}; existing root-only node vault credentials remain in place"
            ));
            Vec::new()
        }
    };
    let target = config
        .nodes
        .get(target_id.as_str())
        .cloned()
        .ok_or_else(|| {
            (
                2,
                format!("controller target '{target_id}' is not configured"),
            )
        })?;
    let current_id = config
        .login_node
        .as_ref()
        .map(|node| node.as_str())
        .or_else(|| {
            config
                .nodes
                .iter()
                .find(|(_, node)| node.transport == Transport::Local)
                .map(|(id, _)| id.as_str())
        });
    if current_id == Some(target_id.as_str()) {
        return Err((2, format!("node '{target_id}' is already the controller")));
    }
    if target.transport != Transport::Ssh {
        return Err((2, "controller target must be a registered SSH node".into()));
    }
    let active = ReadOnlyJobStore::open(state_dir)
        .map_err(|error| (1, error.to_string()))?
        .list_active_jobs()
        .map_err(|error| (1, error.to_string()))?;
    let mut blockers = controller_migration_job_blockers(&active);
    blockers.extend(preflight_warnings);
    if let Err(error) = ensure_no_node_maintenance_in_progress(&config_path, state_dir) {
        blockers.push(error);
    }
    if node_admin_recovery_pending(&config_path, state_dir).map_err(|error| (1, error))? {
        blockers.push("node administration recovery is pending".into());
    }
    if peer_config_sync_pending(&config_path, state_dir).map_err(|error| (1, error))? {
        blockers.push("peer configuration synchronization is pending".into());
    }
    if agent_update_recovery_pending(&config_path, state_dir).map_err(|error| (1, error))? {
        blockers.push("Agent update recovery is pending".into());
    }
    let pending_helpers =
        agent_helper_refresh_pending_nodes(state_dir, &config).map_err(|error| (1, error))?;
    if !pending_helpers.is_empty() {
        blockers.push(format!(
            "privileged helper refresh is deferred for: {}",
            pending_helpers
                .iter()
                .cloned()
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    let binding = ServiceBinding::load(&config_path, state_dir).map_err(|error| {
        (
            1,
            format!("cannot resolve current controller binding: {error}"),
        )
    })?;
    let manager = crate::service::ServiceManager::current(binding.clone()).map_err(|error| {
        (
            1,
            format!("cannot manage current controller service: {error}"),
        )
    })?;
    let inspection = manager
        .inspect(Duration::from_secs(2))
        .map_err(|error| (1, format!("cannot inspect current controller: {error}")))?;
    if inspection.loaded && inspection.hello.is_none() {
        blockers.push("running controller did not expose a verifiable maintenance state".into());
    }
    if inspection.hello.is_some() {
        if !matches!(
            inspection.hello.as_ref().map(|hello| hello.lifecycle),
            Some(macluster_protocol::control::ControllerLifecycle::Ready)
        ) {
            blockers.push(
                "controller is not Ready; migration will stop it and start the target controller"
                    .into(),
            );
        }
        match ControlClient::connect(&binding, MAINTENANCE_CONTROL_TIMEOUT) {
            Ok(mut client) => match client.request(ControlCommand::InspectMaintenance) {
                Ok(ControlPayload::Maintenance(maintenance)) => {
                    if let Some(error) =
                        controller_migration_maintenance_error(maintenance.as_ref())
                    {
                        blockers.push(error);
                    }
                }
                Ok(_) => blockers.push(
                    "controller returned an invalid maintenance status before migration".into(),
                ),
                Err(error) => blockers.push(format!(
                    "controller maintenance state could not be inspected: {error}"
                )),
            },
            Err(error) => blockers.push(format!(
                "controller maintenance state could not be inspected: {error}"
            )),
        }
    }
    let force_migration = !blockers.is_empty();
    if force_migration {
        confirm_force_controller_migration(&blockers)?;
    }
    stage_controller_migration_target_binary(&target)?;
    let facts = read_remote_facts(&target).map_err(|(_, error)| (1, error))?;
    if !remote_os_is_macos(&facts.os) {
        return Err((1, "controller target must be a macOS node".into()));
    }
    let target_home = PathBuf::from(checked_remote_path(&facts.home)?);
    let target_config = target_home.join(".config/macluster/config.toml");
    let target_state = target_home.join("Library/Application Support/macluster/controller");
    let local_binary = std::env::current_exe().map_err(io_error)?;
    let local_hash = local_sha256(&local_binary)?;
    let preflight = controller_migration_target_preflight_script(
        &config.shared_root,
        &config.share_uuid,
        &target_config,
        &target_state,
        &target.remote_binary,
    );
    let preflight =
        run_controller_migration_target_command(&target, &preflight, None, Duration::from_secs(30))
            .map_err(|error| (1, error))?;
    if !preflight.status.success() {
        return Err((
            1,
            format!(
                "controller migration preflight failed: {}",
                command_error("verify target storage, state, and binary", &preflight)
            ),
        ));
    }
    if String::from_utf8_lossy(&preflight.stdout).trim() != local_hash {
        return Err((
            1,
            format!(
                "controller target {} has a different macluster build",
                target_id
            ),
        ));
    }
    let source = fs::read_to_string(&config_path).map_err(io_error)?;
    let candidate =
        controller_migration_candidate(&migration_config, &source, target_id.as_str(), facts.uid)?;
    let candidate = apply_recovered_smb_users(&candidate, &recovered_smb_users)?;
    let candidate_config =
        ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
    let was_running = manager
        .intent()
        .map_err(|error| (1, format!("cannot read controller service intent: {error}")))?
        == macluster_core::service::ServiceIntent::Auto;
    stage_target_smb_masters(
        &smb_masters,
        |provision| run_target_smb_master_command(&target, "import", provision, true),
        |provision| run_target_smb_master_command(&target, "verify", provision, true),
        |provision| {
            let _ = run_target_smb_master_command(&target, "delete", provision, false);
        },
    )
    .map_err(|error| {
        (
            1,
            format!(
                "controller migration could not import and verify SMB master credentials on the target; no controller was stopped: {error}"
            ),
        )
    })?;
    if force_migration {
        force_cancel_migration_jobs(&binding, state_dir, &active);
    }
    if let Err(error) = manager.stop() {
        cleanup_target_smb_masters(&target, &smb_masters);
        return Err((
            1,
            format!(
                "cannot stop the current controller for migration: {error}. Target SMB credentials were cleaned."
            ),
        ));
    }
    let post_stop_active = match ReadOnlyJobStore::open(state_dir)
        .map_err(|error| (1, error.to_string()))
        .and_then(|storage| {
            storage
                .list_active_jobs()
                .map_err(|error| (1, error.to_string()))
        }) {
        Ok(active) => active,
        Err((_, error)) => {
            cleanup_target_smb_masters(&target, &smb_masters);
            let restart = if was_running {
                manager
                    .start(Duration::from_secs(30))
                    .map(|_| ())
                    .map_err(|error| error.to_string())
            } else {
                Ok(())
            };
            let mut message = format!(
                "controller migration could not recheck active jobs after stopping the old controller: {error}. Target SMB credentials were cleaned. No target controller was started."
            );
            if let Err(error) = restart {
                message.push_str(&format!(" Old controller restart failed: {error}."));
            }
            return Err((1, message));
        }
    };
    if let Some(error) = controller_migration_post_stop_error(force_migration, &post_stop_active) {
        cleanup_target_smb_masters(&target, &smb_masters);
        let restart = if was_running {
            manager
                .start(Duration::from_secs(30))
                .map(|_| ())
                .map_err(|error| error.to_string())
        } else {
            Ok(())
        };
        let mut message = format!(
            "controller migration stopped checking the cluster as idle: {error}. Target SMB credentials were cleaned."
        );
        if let Err(error) = restart {
            message.push_str(&format!(" Old controller restart failed: {error}."));
        }
        return Err((1, message));
    }
    let operation_id = Id128::random().to_string();
    let script = controller_migration_target_script(&target, &target_home, &operation_id);
    let restart_old_without_target = |detail: String| -> AppResult<()> {
        cleanup_target_smb_masters(&target, &smb_masters);
        let restart = if was_running {
            manager
                .start(Duration::from_secs(30))
                .map(|_| ())
                .map_err(|error| error.to_string())
        } else {
            Ok(())
        };
        let mut message = format!(
            "controller migration failed before target activation: {detail}. Target SMB credentials were cleaned."
        );
        if let Err(error) = restart {
            message.push_str(&format!(" Old controller restart failed: {error}."));
        }
        Err((1, message))
    };
    set_agent_helper_refresh_pending_nodes(state_dir, pending_helpers);
    let archive = match controller_migration_archive(candidate.as_bytes(), state_dir) {
        Ok(archive) => archive,
        Err((_, error)) => {
            return restart_old_without_target(format!(
                "could not create the controller checkpoint: {error}"
            ));
        }
    };
    let target_failure = |detail: String| -> AppResult<()> {
        cleanup_target_smb_masters(&target, &smb_masters);
        let cleanup_script =
            controller_migration_target_cleanup_script(&target, &target_home, &operation_id);
        let cleanup = run_controller_migration_target_command(
            &target,
            &cleanup_script,
            None,
            Duration::from_secs(30),
        );
        let cleanup_error = match cleanup {
            Ok(output) if output.status.success() => None,
            Ok(output) => Some(command_error(
                "stop and remove the failed target controller",
                &output,
            )),
            Err(error) => Some(error),
        };
        let restart = if controller_migration_may_restart_old(was_running, cleanup_error.is_none())
        {
            manager
                .start(Duration::from_secs(30))
                .map(|_| ())
                .map_err(|error| error.to_string())
        } else {
            Ok(())
        };
        let controller_state = match (was_running, cleanup_error.as_deref(), restart.as_ref()) {
            (false, _, _) => "No old controller was running.",
            (true, None, Ok(())) => "The old controller was restarted after target cleanup.",
            (true, Some(_), _) => {
                "The old controller remains stopped because target cleanup could not be verified; do not start another controller before inspecting the target."
            }
            (true, None, Err(_)) => {
                "The target was cleaned, but the old controller could not be restarted."
            }
        };
        let mut message = format!("controller migration failed: {detail}. {controller_state}");
        if let Some(error) = cleanup_error {
            message.push_str(&format!(" Target cleanup failed: {error}."));
        }
        if let Err(error) = restart {
            message.push_str(&format!(" Old controller restart failed: {error}."));
        }
        Err((1, message))
    };
    let activation = run_controller_migration_target_command(
        &target,
        &script,
        Some(&archive),
        Duration::from_secs(120),
    );
    let activation = match activation {
        Ok(output) if output.status.success() => output,
        Ok(output) => {
            return target_failure(format!(
                "target activation failed: {}",
                command_error("activate controller target", &output)
            ));
        }
        Err(error) => return target_failure(format!("target activation failed: {error}")),
    };
    drop(activation);
    let config_path_text = target_home
        .join(".config/macluster/config.toml")
        .to_string_lossy()
        .into_owned();
    let state_dir_text = target_home
        .join("Library/Application Support/macluster/controller")
        .to_string_lossy()
        .into_owned();
    let verify = format!(
        "{} --config {} --state-dir {} controller status",
        shell_quote(&target.remote_binary),
        shell_quote(&config_path_text),
        shell_quote(&state_dir_text),
    );
    let verified =
        run_controller_migration_target_command(&target, &verify, None, Duration::from_secs(30))
            .and_then(|output| {
                if output.status.success()
                    && String::from_utf8_lossy(&output.stdout).contains("Ready")
                {
                    Ok(output)
                } else {
                    Err(format!(
                        "target did not become Ready: {}",
                        String::from_utf8_lossy(&output.stderr).trim()
                    ))
                }
            });
    let verified = match verified {
        Ok(output) => output,
        Err(error) => return target_failure(error),
    };
    drop(verified);
    let old_helper = macluster_controller::smb_credential::CredentialHelperClient::system();
    for provision in &smb_masters {
        if let Err(error) = old_helper.delete(&provision.key) {
            eprintln!("Warning: old controller SMB master cleanup is deferred: {error}");
            let _ = crate::smb_credentials::queue_global_master_cleanup(&provision.key);
        }
    }
    if let Err(error) = controller_migration_auto_join(&target, &config.share_uuid) {
        let endpoint = controller_migration_join_endpoint(&target)
            .unwrap_or_else(|_| format!("{}@{}", target.host, target.host));
        eprintln!(
            "Warning: controller migration succeeded, but this login client could not be updated automatically: {error}. Run `macluster --join {endpoint}` to finish client setup."
        );
    }
    let local_uuid = crate::app::local_machine_uuid().ok();
    let local_node_id = local_uuid.and_then(|uuid| {
        config
            .nodes
            .iter()
            .find(|(_, node)| {
                node.machine_uuid
                    .as_deref()
                    .is_some_and(|candidate| candidate.eq_ignore_ascii_case(&uuid))
            })
            .map(|(id, _)| id.clone())
    });
    if local_node_id.is_some()
        && let Err((_, error)) = atomic_write(&config_path, candidate.as_bytes())
    {
        eprintln!(
            "Warning: controller migration succeeded, but the local config could not be updated: {error}"
        );
    }
    if let Err(error) = sync_remote_configs(
        &candidate_config,
        &candidate,
        state_dir,
        &Id128::random().to_string(),
        None,
    ) {
        if !controller_migration_peer_sync_error_is_local_only(&error, local_node_id.as_deref()) {
            eprintln!(
                "Warning: controller migration succeeded, but peer config synchronization is deferred: {error}"
            );
        }
    }
    let refresh = format!(
        "{} --config {} --state-dir {} mnode -l >/dev/null",
        shell_quote(&target.remote_binary),
        shell_quote(&config_path_text),
        shell_quote(&state_dir_text),
    );
    if let Err(error) =
        run_controller_migration_target_command(&target, &refresh, None, Duration::from_secs(30))
            .and_then(|output| {
                output.status.success().then_some(()).ok_or_else(|| {
                    command_error("refresh target node health after migration", &output)
                })
            })
    {
        eprintln!(
            "Warning: controller migration succeeded, but target node health refresh is deferred: {error}"
        );
    }
    println!(
        "Controller migrated to {target_id}. This login client now uses the migrated controller."
    );
    Ok(())
}

fn remove_node_from_config(
    source: &str,
    config: &ClusterConfig,
    node_id: &str,
) -> AppResult<String> {
    let mut candidate = source.to_owned();
    for (queue_name, queue) in &config.queues {
        let members: Vec<_> = queue
            .nodes
            .iter()
            .filter(|member| member.as_str() != node_id)
            .cloned()
            .collect();
        candidate = replace_queue_members(&candidate, queue_name, &members)?;
    }
    let section = format!("[nodes.{node_id}]");
    let mut lines: Vec<String> = candidate.lines().map(str::to_owned).collect();
    let Some(start) = lines.iter().position(|line| line.trim() == section) else {
        return Err((2, format!("config has no node section for {node_id}")));
    };
    let end = lines[start + 1..]
        .iter()
        .position(|line| line.trim_start().starts_with('['))
        .map_or(lines.len(), |offset| start + 1 + offset);
    lines.drain(start..end);
    let mut result = lines.join("\n");
    if candidate.ends_with('\n') {
        result.push('\n');
    }
    ClusterConfig::parse(&result).map_err(|error| (2, error.to_string()))?;
    Ok(result)
}

fn mutate_compute_role(
    config_path: &Path,
    state_dir: &Path,
    node_id: &NodeId,
    include: bool,
) -> AppResult<()> {
    let operation_name = if include {
        "compute-role add"
    } else {
        "compute-role remove"
    };
    let maintenance = acquire_node_maintenance_scoped(
        config_path,
        state_dir,
        operation_name,
        MaintenanceScope::Cluster,
    )?;
    let result = (|| -> AppResult<()> {
        MaintenanceLock::bind_state_dir(config_path, state_dir).map_err(|error| {
            (
                1,
                format!("cluster config/state directory binding failed: {error}"),
            )
        })?;
        let config_path = config_path.canonicalize().map_err(io_error)?;
        let source = fs::read_to_string(&config_path).map_err(io_error)?;
        let config = ClusterConfig::parse(&source).map_err(|error| (2, error.to_string()))?;
        if !config.nodes.contains_key(node_id.as_str()) {
            return Err((2, format!("node '{node_id}' is not configured")));
        }
        if !include {
            let storage = Storage::open(state_dir).map_err(|error| (1, error.to_string()))?;
            let blockers = storage
                .jobs_preventing_node_removal(node_id.as_str())
                .map_err(|error| (1, error.to_string()))?;
            if !blockers.is_empty() {
                return Err((
                    1,
                    format!(
                        "cannot remove the compute role from {node_id} while jobs remain: {}",
                        blockers
                            .iter()
                            .map(|job| job.id.to_string())
                            .collect::<Vec<_>>()
                            .join(", ")
                    ),
                ));
            }
        }
        let candidate = compute_role_candidate(&config, &source, node_id.as_str(), include)?;
        let candidate_config =
            ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
        let operation_id = Id128::random().to_string();
        backup_config(&config_path, &operation_id)?;
        atomic_write(&config_path, candidate.as_bytes())?;
        sync_remote_configs_online_nodes(
            &candidate_config,
            &candidate,
            state_dir,
            &operation_id,
        )
        .map_err(|error| {
            (
                1,
                format!(
                    "compute role was changed locally for {node_id}, but peer config sync failed: {error}"
                ),
            )
        })?;
        if include {
            println!(
                "Node {node_id} now has the compute role and belongs to queue {}.",
                candidate_config.default_queue
            );
        } else {
            println!("Node {node_id} no longer has the compute role.");
        }
        Ok(())
    })();
    finish_node_maintenance(maintenance, result)
}

fn external_storage_config_candidate(
    config: &ClusterConfig,
    source: &str,
    node_id: &NodeId,
    host: &str,
) -> AppResult<String> {
    if !valid_storage_host(host) {
        return Err((
            2,
            "storage provider host must be an IPv4 address or DNS name".into(),
        ));
    }
    if let Some(existing) = config.nodes.get(node_id.as_str()) {
        if existing.transport == Transport::Storage && existing.host == host {
            return Ok(source.to_owned());
        }
        if existing.transport == Transport::Storage && existing.host == node_id.as_str() {
            let entry = format!("[nodes.{node_id}]\nhost = \"{host}\"\ntransport = \"storage\"\n");
            let candidate = replace_or_append_table(source, &format!("[nodes.{node_id}]"), &entry);
            ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
            return Ok(candidate);
        }
        return Err((
            2,
            format!("node '{node_id}' is already configured with a different transport or host"),
        ));
    }
    let entry = format!("[nodes.{node_id}]\nhost = \"{host}\"\ntransport = \"storage\"\n");
    let candidate = replace_or_append_table(source, &format!("[nodes.{node_id}]"), &entry);
    ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
    Ok(candidate)
}

fn register_storage_provider(
    config_path: &Path,
    state_dir: &Path,
    node_id: &NodeId,
    host: &str,
) -> AppResult<()> {
    let maintenance = acquire_node_maintenance_scoped(
        config_path,
        state_dir,
        "storage provider registration",
        MaintenanceScope::Cluster,
    )?;
    let result = (|| -> AppResult<()> {
        MaintenanceLock::bind_state_dir(config_path, state_dir).map_err(|error| {
            (
                1,
                format!("cluster config/state directory binding failed: {error}"),
            )
        })?;
        let config_path = config_path.canonicalize().map_err(io_error)?;
        let source = fs::read_to_string(&config_path).map_err(io_error)?;
        let config = ClusterConfig::parse(&source).map_err(|error| (2, error.to_string()))?;
        let candidate = external_storage_config_candidate(&config, &source, node_id, host)?;
        if candidate == source {
            return Ok(());
        }
        let candidate_config =
            ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
        let operation_id = Id128::random().to_string();
        backup_config(&config_path, &operation_id)?;
        atomic_write(&config_path, candidate.as_bytes())?;
        sync_remote_configs_online_nodes(
            &candidate_config,
            &candidate,
            state_dir,
            &operation_id,
        )
        .map_err(|error| {
            (1, format!("storage provider {node_id} was registered locally, but peer config sync failed: {error}"))
        })?;
        Ok(())
    })();
    finish_node_maintenance(maintenance, result)
}

fn remove_unused_storage_provider(
    source: &str,
    config: &ClusterConfig,
    node_id: &str,
) -> AppResult<String> {
    let Some(node) = config.nodes.get(node_id) else {
        return Ok(source.to_owned());
    };
    if node.transport != Transport::Storage
        || config.storage_server.as_str() == node_id
        || config
            .shares
            .values()
            .any(|share| share.server.as_str() == node_id)
    {
        return Ok(source.to_owned());
    }
    remove_node_from_config(source, config, node_id)
}

fn atomic_write(path: &Path, bytes: &[u8]) -> AppResult<()> {
    let parent = path
        .parent()
        .ok_or_else(|| (1, "managed file has no parent directory".into()))?;
    fs::create_dir_all(parent).map_err(io_error)?;
    let temp = parent.join(format!(
        ".{}.{}.tmp",
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("macluster"),
        Id128::random()
    ));
    let result = (|| -> io::Result<()> {
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&temp)?;
        file.write_all(bytes)?;
        file.sync_all()?;
        fs::rename(&temp, path)?;
        File::open(parent)?.sync_all()?;
        Ok(())
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temp);
    }
    result.map_err(io_error)
}

fn backup_config(path: &Path, operation_id: &str) -> AppResult<()> {
    let backup = path.with_file_name(format!(
        "{}.macluster-{operation_id}.bak",
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("config")
    ));
    if !backup.exists() {
        fs::copy(path, &backup).map_err(io_error)?;
        let file = OpenOptions::new()
            .read(true)
            .open(&backup)
            .map_err(io_error)?;
        file.sync_all().map_err(io_error)?;
    }
    Ok(())
}

fn read_config_backup_for_digest(
    config_path: &Path,
    expected_digest: &str,
) -> AppResult<Option<ClusterConfig>> {
    if expected_digest.len() != 64 || !expected_digest.bytes().all(|byte| byte.is_ascii_hexdigit())
    {
        return Err((
            1,
            "pending share journal contains an invalid previous config digest".into(),
        ));
    }
    let parent = config_path.parent().ok_or_else(|| {
        (
            1,
            format!(
                "cannot locate previous config snapshot beside {}",
                config_path.display()
            ),
        )
    })?;
    let file_name = config_path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("config");
    let prefix = format!("{file_name}.macluster-");
    let entries = fs::read_dir(parent).map_err(io_error)?;
    for entry in entries {
        let entry = entry.map_err(io_error)?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if !name.starts_with(&prefix) || !name.ends_with(".bak") {
            continue;
        }
        let metadata = fs::symlink_metadata(entry.path()).map_err(io_error)?;
        if !metadata.is_file()
            || metadata.file_type().is_symlink()
            || metadata.len() > 4 * 1024 * 1024
        {
            continue;
        }
        let bytes = fs::read(entry.path()).map_err(io_error)?;
        if sha256_hex(&bytes).map_err(|error| (1, error.to_string()))? != expected_digest {
            continue;
        }
        let source = std::str::from_utf8(&bytes).map_err(|error| {
            (
                1,
                format!("previous config snapshot is not valid UTF-8: {error}"),
            )
        })?;
        let snapshot = ClusterConfig::parse(source)
            .map_err(|error| (1, format!("previous config snapshot is invalid: {error}")))?;
        return Ok(Some(snapshot));
    }
    Ok(None)
}

fn same_pending_share_topology(current: &ClusterConfig, previous: &ClusterConfig) -> bool {
    current.login_node == previous.login_node
        && current.storage_server == previous.storage_server
        && current.nodes == previous.nodes
}

fn remote_node_check(node: &NodeConfig, node_id: &str) -> AppResult<NodeCheck> {
    let mut args = vec![node.remote_binary.as_str()];
    if let Some(config_path) = node.remote_config.as_deref() {
        args.extend(["--config", config_path]);
    }
    args.extend(["internal", "node-check", "--node", node_id]);
    let command = shell_join(&args);
    let output = ssh_output(node, &command, None)?;
    if !output.status.success() {
        return Err((1, command_error("remote node check failed", &output)));
    }
    let report: NodeCheck = serde_json::from_slice(&output.stdout).map_err(|error| {
        (
            1,
            format!("remote node check returned invalid JSON: {error}"),
        )
    })?;
    if report.node != node_id {
        return Err((1, "remote node check returned a different node ID".into()));
    }
    Ok(report)
}

pub(crate) fn read_remote_facts(node: &NodeConfig) -> AppResult<RemoteFacts> {
    let command = "printf 'OS='; /usr/bin/uname -s; printf 'ARCH='; /usr/bin/uname -m; printf 'VERSION='; /usr/bin/sw_vers -productVersion; printf 'UID='; /usr/bin/id -u; printf 'GID='; /usr/bin/id -g; printf 'HOME='; /usr/bin/printenv HOME; printf 'FREE_KB='; /bin/df -Pk \"$HOME\" | /usr/bin/tail -1 | /usr/bin/awk '{print $4}'";
    let output = ssh_output(node, command, None)?;
    if !output.status.success() {
        return Err((1, command_error("SSH preflight failed", &output)));
    }
    parse_remote_facts(&output)
}

fn parse_remote_facts(output: &Output) -> AppResult<RemoteFacts> {
    let mut facts = BTreeMap::new();
    for line in String::from_utf8_lossy(&output.stdout).lines() {
        if let Some((key, value)) = line.split_once('=') {
            facts.insert(key.trim().to_owned(), value.trim().to_owned());
        }
    }
    let get = |key: &str| {
        facts
            .get(key)
            .cloned()
            .ok_or_else(|| (1, format!("remote preflight omitted {key}")))
    };
    Ok(RemoteFacts {
        os: get("OS")?,
        arch: get("ARCH")?,
        version: get("VERSION")?,
        uid: get("UID")?
            .parse()
            .map_err(|_| (1, "remote UID was not numeric".into()))?,
        gid: get("GID")?
            .parse()
            .map_err(|_| (1, "remote GID was not numeric".into()))?,
        home: get("HOME")?,
        free_kb: get("FREE_KB")?
            .parse()
            .map_err(|_| (1, "remote free disk size was not numeric".into()))?,
    })
}

fn remote_os_is_macos(value: &str) -> bool {
    value.eq_ignore_ascii_case("darwin") || value.eq_ignore_ascii_case("macos")
}

fn parse_security_internet_account(output: &str) -> Option<String> {
    output.lines().find_map(|line| {
        let (_, value) = line.trim().split_once("\"acct\"<blob>=")?;
        let account = value.trim().trim_matches('"');
        valid_smb_user(account).then(|| account.to_owned())
    })
}

fn recover_missing_smb_users(
    config: &ClusterConfig,
) -> (ClusterConfig, BTreeMap<String, String>, Vec<String>) {
    let mut recovered_config = config.clone();
    let mut recovered = BTreeMap::new();
    let mut warnings = Vec::new();
    for (share_id, share) in &mut recovered_config.shares {
        if share.protocol != StorageProtocol::Smb || share.smb_user.is_some() {
            continue;
        }
        let Some(server) = config.nodes.get(share.server.as_str()) else {
            warnings.push(format!(
                "SMB mapping {share_id} uses missing server {}",
                share.server
            ));
            continue;
        };
        let account = Command::new("/usr/bin/security")
            .args(["find-internet-password", "-s", &server.host])
            .output()
            .ok()
            .filter(|output| output.status.success())
            .and_then(|output| {
                parse_security_internet_account(&String::from_utf8_lossy(&output.stdout))
            });
        match account {
            Some(account) => {
                share.smb_user = Some(account.clone());
                recovered.insert(share_id.clone(), account);
            }
            None => warnings.push(format!(
                "SMB account metadata is missing for {share_id} on {}",
                server.host
            )),
        }
    }
    (recovered_config, recovered, warnings)
}

fn apply_recovered_smb_users(
    candidate: &str,
    recovered: &BTreeMap<String, String>,
) -> AppResult<String> {
    let mut candidate = candidate.to_owned();
    for (share_id, account) in recovered {
        candidate = replace_section_key(
            &candidate,
            &format!("[shares.{share_id}]"),
            "smb_user",
            &format!("\"{account}\""),
        )?;
    }
    Ok(candidate)
}

fn remote_route_ipv4(node: &NodeConfig, destination: &str) -> AppResult<Ipv4Addr> {
    let route = shell_join(&["/sbin/route", "-n", "get", destination]);
    let output = ssh_output(node, &route, None)?;
    if !output.status.success() {
        return Err((
            1,
            command_error("cannot inspect route to NFS server", &output),
        ));
    }
    let text = String::from_utf8_lossy(&output.stdout);
    let interface = text
        .lines()
        .find_map(|line| line.trim().strip_prefix("interface: "))
        .ok_or_else(|| (1, "route output did not include an interface".into()))?;
    let command = shell_join(&["/sbin/ifconfig", interface]);
    let output = ssh_output(node, &command, None)?;
    if !output.status.success() {
        return Err((
            1,
            command_error("cannot inspect selected network interface", &output),
        ));
    }
    parse_ifconfig_ipv4(&String::from_utf8_lossy(&output.stdout))
        .into_iter()
        .next()
        .ok_or_else(|| {
            (
                1,
                "selected network interface has no usable IPv4 address".into(),
            )
        })
}

pub(crate) fn ensure_agent_capabilities(node: &NodeConfig) -> AppResult<()> {
    let output = if node.transport == Transport::Local {
        let mut command = Command::new(&node.remote_binary);
        command.args(["internal", "capabilities", "--json"]);
        run_child(command, None, Duration::from_secs(5))?
    } else {
        let command = shell_join(&[&node.remote_binary, "internal", "capabilities", "--json"]);
        ssh_output(node, &command, None)?
    };
    if !output.status.success() {
        return Err((1, command_error("agent capability check failed", &output)));
    }
    let report: CapabilityReport = serde_json::from_slice(&output.stdout).map_err(|error| {
        (
            1,
            format!("agent capability report was invalid JSON: {error}"),
        )
    })?;
    if report.build_id.as_deref() != Some(macluster_protocol::BUILD_ID) {
        return Err((
            1,
            format!(
                "agent on {} has build {:?}; expected {}",
                node.host,
                report.build_id,
                macluster_protocol::BUILD_ID
            ),
        ));
    }
    let missing = missing_required_agent_features(&report.features);
    if !missing.is_empty() {
        return Err((
            1,
            format!(
                "agent on {} does not support required feature(s): {}; upgrade it with the current macluster binary before changing cluster config",
                node.host,
                missing.join(", ")
            ),
        ));
    }
    Ok(())
}

pub(crate) fn stage_current_agents(
    config: &ClusterConfig,
    source: &str,
    operation_id: &str,
    purpose: AgentStagePurpose,
) -> AppResult<(String, ClusterConfig)> {
    stage_current_agents_for_nodes(config, source, operation_id, purpose, None)
}

fn stage_current_agents_for_nodes(
    config: &ClusterConfig,
    source: &str,
    operation_id: &str,
    purpose: AgentStagePurpose,
    included_nodes: Option<&BTreeSet<String>>,
) -> AppResult<(String, ClusterConfig)> {
    let mut candidate = source.to_owned();
    let local_binary = std::env::current_exe()
        .map_err(io_error)?
        .canonicalize()
        .map_err(io_error)?;
    let local_binary_text = local_binary
        .to_str()
        .ok_or_else(|| (1, "current macluster binary path is not UTF-8".into()))?;
    if !safe_absolute_binary_path(local_binary_text) {
        return Err((
            1,
            "current macluster binary path cannot be stored safely in TOML".into(),
        ));
    }
    for (node_id, node) in &config.nodes {
        if !config.is_operational_node(node_id) {
            continue;
        }
        if included_nodes.is_some_and(|nodes| !nodes.contains(node_id)) {
            continue;
        }
        let (destination, machine_uuid, execution_uid, remote_arch) = if node.transport
            == Transport::Local
        {
            let machine_uuid = local_platform_uuid()?;
            let execution_uid = unsafe { libc::geteuid() };
            if node
                .machine_uuid
                .as_deref()
                .is_some_and(|expected| !expected.eq_ignore_ascii_case(&machine_uuid))
                || node
                    .execution_uid
                    .is_some_and(|expected| expected != execution_uid)
            {
                return Err((
                    1,
                    format!(
                        "local node {node_id} no longer matches its registered machine UUID or execution UID: expected {}:{}, got {machine_uuid}:{execution_uid}",
                        node.machine_uuid.as_deref().unwrap_or("<unset>"),
                        node.execution_uid
                            .map(|uid| uid.to_string())
                            .unwrap_or_else(|| "<unset>".into())
                    ),
                ));
            }
            ensure_agent_capabilities(&NodeConfig {
                remote_binary: local_binary_text.into(),
                ..node.clone()
            })
            .map_err(|(_, error)| (1, format!("node {node_id}: {error}")))?;
            (
                local_binary_text.to_owned(),
                machine_uuid,
                execution_uid,
                std::env::consts::ARCH.to_owned(),
            )
        } else {
            let facts = read_remote_facts(node)
                .map_err(|(_, error)| (1, format!("cannot inspect node {node_id}: {error}")))?;
            let machine_uuid = remote_machine_uuid(node).map_err(|(_, error)| {
                (1, format!("cannot verify node {node_id} identity: {error}"))
            })?;
            if node
                .machine_uuid
                .as_deref()
                .is_some_and(|expected| !expected.eq_ignore_ascii_case(&machine_uuid))
                || node
                    .execution_uid
                    .is_some_and(|expected| expected != facts.uid)
            {
                return Err((
                    1,
                    format!(
                        "node {node_id} no longer matches its registered machine UUID or execution UID: expected {}:{}, got {machine_uuid}:{}",
                        node.machine_uuid.as_deref().unwrap_or("<unset>"),
                        node.execution_uid
                            .map(|uid| uid.to_string())
                            .unwrap_or_else(|| "<unset>".into()),
                        facts.uid
                    ),
                ));
            }
            let binary = select_local_binary(&facts.arch)?;
            let digest = local_sha256(&binary)?;
            let home = checked_remote_path(&facts.home)?;
            let path = format!(
                "{home}/.local/share/macluster/clusters/{}/bin/{digest}/macluster",
                config.share_uuid
            );
            let mut staged = node.clone();
            staged.remote_binary = path.clone();
            ensure_remote_binary(&staged, &binary, &facts.version, operation_id).map_err(
                |(_, error)| {
                    (
                        1,
                        format!("cannot stage current agent on {node_id}: {error}"),
                    )
                },
            )?;
            ensure_agent_capabilities(&staged)
                .map_err(|(_, error)| (1, format!("node {node_id}: {error}")))?;
            (path, machine_uuid, facts.uid, facts.arch)
        };
        if purpose.installs_power_helper() {
            if let Err(error) = ensure_power_helper(node, execution_uid, &remote_arch, operation_id)
            {
                eprintln!("Power sampler setup for {node_id} was skipped: {error}");
            }
        }
        candidate = replace_node_string_key(&candidate, node_id, "remote_binary", &destination)?;
        candidate = replace_node_string_key(&candidate, node_id, "machine_uuid", &machine_uuid)?;
        candidate = replace_node_integer_key(&candidate, node_id, "execution_uid", execution_uid)?;
    }
    let candidate_config =
        ClusterConfig::parse(&candidate).map_err(|error| (2, error.to_string()))?;
    Ok((candidate, candidate_config))
}

fn replace_node_string_key(
    source: &str,
    node_id: &str,
    key: &str,
    value: &str,
) -> AppResult<String> {
    let section = format!("[nodes.{node_id}]");
    let mut lines: Vec<String> = source.lines().map(str::to_owned).collect();
    let start = lines
        .iter()
        .position(|line| line.trim() == section)
        .ok_or_else(|| (2, format!("config is missing {section}")))?;
    let end = lines[start + 1..]
        .iter()
        .position(|line| line.trim_start().starts_with('['))
        .map_or(lines.len(), |offset| start + 1 + offset);
    if let Some(index) = (start + 1..end).find(|index| {
        lines[*index]
            .split_once('=')
            .is_some_and(|(existing, _)| existing.trim() == key)
    }) {
        lines[index] = format!("{key} = \"{value}\"");
    } else {
        lines.insert(end, format!("{key} = \"{value}\""));
    }
    Ok(lines.join("\n") + if source.ends_with('\n') { "\n" } else { "" })
}

fn replace_node_integer_key(
    source: &str,
    node_id: &str,
    key: &str,
    value: u32,
) -> AppResult<String> {
    let section = format!("[nodes.{node_id}]");
    let mut lines: Vec<String> = source.lines().map(str::to_owned).collect();
    let start = lines
        .iter()
        .position(|line| line.trim() == section)
        .ok_or_else(|| (2, format!("config is missing {section}")))?;
    let end = lines[start + 1..]
        .iter()
        .position(|line| line.trim_start().starts_with('['))
        .map_or(lines.len(), |offset| start + 1 + offset);
    if let Some(index) = (start + 1..end).find(|index| {
        lines[*index]
            .split_once('=')
            .is_some_and(|(existing, _)| existing.trim() == key)
    }) {
        lines[index] = format!("{key} = {value}");
    } else {
        lines.insert(end, format!("{key} = {value}"));
    }
    Ok(lines.join("\n") + if source.ends_with('\n') { "\n" } else { "" })
}

pub(crate) fn remote_machine_uuid(node: &NodeConfig) -> AppResult<String> {
    let output = ssh_output(node, "/usr/sbin/ioreg -rd1 -c IOPlatformExpertDevice", None)?;
    parse_remote_machine_uuid(&output)
}

fn removal_remote_machine_uuid(node: &NodeConfig) -> AppResult<String> {
    let output = ssh_output_with_timeout(
        node,
        "/usr/sbin/ioreg -rd1 -c IOPlatformExpertDevice",
        None,
        REMOVAL_IDENTITY_TIMEOUT,
    )?;
    parse_remote_machine_uuid(&output)
}

fn parse_remote_machine_uuid(output: &Output) -> AppResult<String> {
    if !output.status.success() {
        return Err((1, command_error("could not read machine identity", output)));
    }
    let text = String::from_utf8_lossy(&output.stdout);
    let value = text
        .lines()
        .find(|line| line.contains("IOPlatformUUID"))
        .and_then(|line| line.rsplit_once('=').map(|(_, value)| value.trim()))
        .map(|value| value.trim_matches('"').trim())
        .ok_or_else(|| (1, "remote IOPlatformUUID was not present".into()))?;
    Id128::parse(value).map_err(|error| (1, format!("invalid remote platform UUID: {error}")))?;
    Ok(value.to_ascii_lowercase())
}

pub(crate) fn checked_remote_path(path: &str) -> AppResult<String> {
    if !safe_absolute_remote_path(path) {
        return Err((
            2,
            "remote HOME must be a normalized absolute path containing only ASCII letters, digits, '/', '.', '_' or '-'".into(),
        ));
    }
    Ok(path.to_owned())
}

pub(crate) fn reset_admin_operations(
    config_path: &Path,
    state_dir: &Path,
) -> AppResult<Vec<ResetAdminOperation>> {
    let canonical_config = config_path
        .canonicalize()
        .unwrap_or_else(|_| config_path.to_path_buf());
    let canonical_state = state_dir
        .canonicalize()
        .unwrap_or_else(|_| state_dir.to_path_buf());
    let state = read_admin_state(
        &state_dir.join("node-admin.json"),
        &canonical_config,
        &canonical_state,
    )?;
    Ok(state
        .operations
        .into_values()
        .map(|operation| {
            let client_setup_may_have_run = pending_add_may_have_client_state(&operation);
            ResetAdminOperation {
                id: operation.id,
                action: operation.action,
                connection_endpoint: operation.connection_endpoint,
                remote_config_path: operation.remote_config_path,
                node_id: operation.node_id,
                endpoint: operation.endpoint,
                machine_uuid: operation.machine_uuid,
                phase: operation.phase,
                old_config_sha256: operation.old_config_sha256,
                candidate_config_sha256: operation.candidate_config_sha256,
                client_setup_may_have_run,
            }
        })
        .collect())
}

pub(crate) fn reset_node_from_endpoint(
    endpoint: &str,
    machine_uuid: Option<String>,
) -> AppResult<NodeConfig> {
    let parsed = NodeEndpoint::parse(endpoint).map_err(|error| {
        (
            1,
            format!("cannot identify pending node endpoint '{endpoint}': {error}"),
        )
    })?;
    if parsed.source_path.is_some() {
        return Err((
            1,
            format!("pending node endpoint '{endpoint}' unexpectedly contains a source path"),
        ));
    }
    let local = parsed.user == "local";
    let ssh_identity_file = if local {
        None
    } else {
        let home = std::env::var_os("HOME").map(PathBuf::from).ok_or_else(|| {
            (
                1,
                "cannot find the login account's HOME to resume SSH access".to_owned(),
            )
        })?;
        crate::ssh_bootstrap::existing_ssh_identity_file(&home, &parsed.ssh_identity_endpoint())
            .map_err(|error| (1, error))?
            .map(|path| path.to_string_lossy().into_owned())
    };
    Ok(NodeConfig {
        host: parsed.host.to_string(),
        transport: if local {
            Transport::Local
        } else {
            Transport::Ssh
        },
        remote_binary: "/usr/local/bin/macluster".into(),
        ssh_user: (!local).then_some(parsed.user),
        ssh_port: (!local).then_some(parsed.port),
        ssh_identity_file,
        remote_config: None,
        machine_uuid,
        execution_uid: None,
    })
}

