    #[test]
    fn remote_config_allows_a_verified_controller_role_migration() {
        let old = ClusterConfig::parse(
            r#"[cluster]
name = "test"
default_queue = "default"
login_node = "login"
shared_root = "/Users/Shared/test"
share_uuid = "00000000-0000-4000-8000-000000000001"
storage_server = "login"
protocol_version = 1
[queues.default]
nodes = ["login", "controller"]
scheduler = "fifo"
[nodes.login]
host = "192.0.2.1"
transport = "local"
machine_uuid = "01234567-89ab-cdef-0123-456789abcdef"
execution_uid = 501
[nodes.controller]
host = "192.0.2.2"
transport = "ssh"
machine_uuid = "11234567-89ab-cdef-0123-456789abcdef"
execution_uid = 501
"#,
        )
        .unwrap();
        let mut migrated = old.clone();
        migrated.login_node = Some(NodeId::new("controller").unwrap());
        migrated.nodes.get_mut("login").unwrap().transport = Transport::Ssh;
        migrated.nodes.get_mut("controller").unwrap().transport = Transport::Local;

        assert!(remote_config_belongs_to_cluster(&old, &migrated, None));

        migrated.nodes.get_mut("login").unwrap().machine_uuid =
            Some("21234567-89ab-cdef-0123-456789abcdef".into());
        assert!(!remote_config_belongs_to_cluster(&old, &migrated, None));
    }

    #[test]
    fn auto_updated_agent_receipt_matches_only_the_same_node_and_running_binary() {
        let mut config = parse_build_test_config();
        let node_id = "arm-a";
        let node = config.nodes.get_mut(node_id).unwrap();
        node.machine_uuid = Some("01234567-89ab-cdef-0123-456789abcdef".into());
        node.execution_uid = Some(501);
        node.remote_binary = format!(
            "/Users/test/.local/share/macluster/clusters/{}/bin/{}/macluster",
            config.share_uuid,
            "a".repeat(64)
        );
        let digest = super::current_agent_sha256().unwrap();
        let fingerprint =
            macluster_controller::ssh::ConnectionKey::for_node(&config.share_uuid, node_id, node)
                .unwrap()
                .cache_fingerprint()
                .unwrap();
        let entry = macluster_core::agent_update::AutoAgentUpdateEntry {
            remote_binary: node.remote_binary.clone(),
            machine_uuid: node.machine_uuid.clone().unwrap(),
            execution_uid: 501,
            connection_fingerprint: fingerprint,
            build_id: macluster_protocol::BUILD_ID.to_owned(),
            sha256: digest.clone(),
        };
        let receipts = macluster_core::agent_update::AutoAgentUpdateReceipts {
            schema: 1,
            nodes: BTreeMap::from([(node_id.into(), entry)]),
        };
        assert!(super::auto_agent_update_receipt_matches(
            &receipts,
            &config,
            node_id,
            &config.nodes[node_id],
        ));

        let receipt_root = test_exports_path();
        receipts.save_to_dir(&receipt_root).unwrap();
        let mut compatibility = AgentBuildCompatibility {
            stale: vec![node_id.into()],
            ..AgentBuildCompatibility::default()
        };
        super::apply_auto_agent_update_receipts(&config, &receipt_root, &mut compatibility);
        assert!(compatibility.stale.is_empty());
        assert_eq!(compatibility.current, vec![node_id]);
        fs::remove_dir_all(receipt_root).unwrap();

        let mut changed_config = config.clone();
        changed_config.nodes.get_mut(node_id).unwrap().host = "192.0.2.99".into();
        assert!(!super::auto_agent_update_receipt_matches(
            &receipts,
            &changed_config,
            node_id,
            &changed_config.nodes[node_id],
        ));
        let mut stale_receipts = receipts.clone();
        stale_receipts.nodes.get_mut(node_id).unwrap().build_id = "older-build".into();
        assert!(!super::auto_agent_update_receipt_matches(
            &stale_receipts,
            &config,
            node_id,
            &config.nodes[node_id],
        ));
    }

    #[test]
    fn legacy_agent_probe_requires_a_valid_hash_and_reports_version() {
        let digest = "a".repeat(64);
        let parsed = parse_agent_build_probe(&format!(
            "VERSION=macluster 0.1.0 (protocol 1)\nSHA256={digest}\n"
        ))
        .unwrap();
        assert_eq!(parsed.version, "macluster 0.1.0 (protocol 1)");
        assert_eq!(parsed.sha256, Some(digest));
        let version_only =
            parse_agent_build_probe("VERSION=macluster 0.1.0\nSHA256=bad\n").unwrap();
        assert_eq!(version_only.version, "macluster 0.1.0");
        assert_eq!(version_only.sha256, None);
    }

    #[test]
    fn local_agent_build_is_classified_by_file_digest() {
        let root = test_exports_path();
        fs::create_dir_all(&root).unwrap();
        let binary = root.join("macluster");
        fs::write(&binary, b"current local agent").unwrap();
        let node = NodeConfig {
            host: "127.0.0.1".into(),
            transport: Transport::Local,
            remote_binary: binary.display().to_string(),
            ssh_user: None,
            ssh_port: None,
            ssh_identity_file: None,
            remote_config: None,
            machine_uuid: None,
            execution_uid: None,
        };
        let digest = sha256_hex(b"current local agent").unwrap();
        assert_eq!(
            inspect_configured_agent_build(&node, &digest),
            AgentBuildState::Current
        );
        assert_eq!(
            inspect_configured_agent_build(&node, &sha256_hex(b"different agent").unwrap()),
            AgentBuildState::Stale
        );
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn global_agent_classification_includes_login_and_all_queues() {
        let config = parse_build_test_config();
        let compatibility = classify_configured_agents(&config, |node_id, _| match node_id {
            "login" => AgentBuildState::Current,
            "arm-a" => AgentBuildState::Current,
            "arm-b" => AgentBuildState::Stale,
            _ => AgentBuildState::Unknown,
        });
        assert_eq!(compatibility.current, ["arm-a", "login"]);
        assert_eq!(compatibility.stale, ["arm-b"]);
        assert!(compatibility.requires_update());

        let unknown = classify_configured_agents(&config, |_, _| AgentBuildState::Unknown);
        assert_eq!(unknown.unknown, ["arm-a", "arm-b", "login"]);
        assert!(!unknown.requires_update());
    }

    #[test]
    fn agent_validation_cache_key_changes_when_ssh_identity_changes() {
        let root = test_exports_path();
        fs::create_dir_all(&root).unwrap();
        let identity = root.join("id_ed25519");
        fs::write(&identity, b"first-key-material").unwrap();
        let mut config = parse_build_test_config();
        config.nodes.get_mut("arm-a").unwrap().ssh_identity_file =
            Some(identity.display().to_string());
        let first =
            super::agent_validation_cache_key_with_offline(&config, &BTreeSet::new()).unwrap();
        fs::write(&identity, b"rotated-key-material-with-new-size").unwrap();
        let second =
            super::agent_validation_cache_key_with_offline(&config, &BTreeSet::new()).unwrap();
        assert_ne!(first, second);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn confirmed_offline_probe_exclusions_require_matching_identity_and_threshold() {
        let config = parse_build_test_config();
        let offline = macluster_controller::liveness::NodeLiveness {
            identity_key: config.nodes["arm-a"].host.to_ascii_lowercase(),
            unreachable_since_unix_ms: Some(1),
            consecutive_failures: macluster_controller::liveness::OFFLINE_AFTER_FAILURES,
            ..Default::default()
        };
        let reconnecting = macluster_controller::liveness::NodeLiveness {
            identity_key: config.nodes["arm-b"].host.to_ascii_lowercase(),
            unreachable_since_unix_ms: Some(1),
            consecutive_failures: macluster_controller::liveness::OFFLINE_AFTER_FAILURES - 1,
            ..Default::default()
        };
        let mismatched = macluster_controller::liveness::NodeLiveness {
            identity_key: "different-machine-uuid".into(),
            unreachable_since_unix_ms: Some(1),
            consecutive_failures: macluster_controller::liveness::OFFLINE_AFTER_FAILURES,
            ..Default::default()
        };
        let records = BTreeMap::from([
            ("arm-a".into(), offline),
            ("arm-b".into(), reconnecting),
            ("login".into(), mismatched),
        ]);

        assert_eq!(
            super::confirmed_offline_probe_exclusions(&config, &records),
            BTreeSet::from(["arm-a".to_owned()])
        );
    }

