    #[test]
    fn local_address_policy_requires_explicit_change_for_inactive_registration() {
        let mut config = parse_build_test_config();
        config.nodes.get_mut("login").unwrap().host = "192.0.2.2".into();
        let replacement = "198.51.100.5".parse().unwrap();
        let addresses = [replacement];
        let error = preferred_local_host(&config, None, &addresses).unwrap_err();
        assert!(error.1.contains("192.0.2.2"), "{error:?}");
        assert!(error.1.contains("--host"), "{error:?}");
        assert_eq!(
            preferred_local_host(&config, Some(replacement), &addresses).unwrap(),
            Some(replacement)
        );
        assert!(
            preferred_local_host(&config, Some("198.18.2.9".parse().unwrap()), &addresses)
                .is_err()
        );
        config.nodes.remove("login");
        assert_eq!(
            preferred_local_host(&config, None, &addresses).unwrap(),
            None
        );
    }

    #[test]
    fn nfs_mapping_details_distinguish_local_alias_and_mount_with_per_share_health() {
        let mut config = parse_build_test_config();
        config.shares.insert(
            "JanusX".into(),
            ShareConfig {
                protocol: macluster_core::storage_uri::StorageProtocol::Nfs,
                server: NodeId::new("login").unwrap(),
                source_root: "/Users/example/script/JanusX".into(),
                mount_root: "/Users/Shared/JanusX".into(),
                share_uuid: "00000000-0000-4000-8000-000000000002".into(),
                smb_user: None,
                allow_existing_contents: false,
            },
        );
        let mut health = NodeHealth {
            machine_uuid: config.nodes["login"].machine_uuid.clone().unwrap(),
            execution_uid: 501,
            build_id: Some(macluster_protocol::BUILD_ID.to_owned()),
            logical_cpus: None,
            execution_digest: config.execution_digest().unwrap(),
            primary_share_ready: true,
            shares: BTreeMap::from([("JanusX".into(), false)]),
            features: Vec::new(),
            ..Default::default()
        };
        let server = node_nfs_mappings(&config, "login", Some(&health));
        assert_eq!(server[0].name, "primary");
        assert_eq!(
            server[0].protocol,
            macluster_core::storage_uri::StorageProtocol::Nfs
        );
        assert_eq!(server[0].kind, "LOCAL");
        assert_eq!(server[0].state, "READY");
        assert_eq!(server[0].source_node, "login");
        assert_eq!(server[0].target, "/tmp/macluster-shared");
        assert_eq!(server[1].name, "JanusX");
        assert_eq!(server[1].kind, "ALIAS");
        assert_eq!(server[1].state, "PENDING");
        assert_eq!(server[1].source_node, "login");
        assert_eq!(server[1].target, "/Users/Shared/JanusX");

        let client = node_nfs_mappings(&config, "arm-a", Some(&health));
        assert!(client.iter().all(|mapping| mapping.kind == "MOUNT"));
        let offline = node_nfs_mappings(&config, "arm-a", None);
        assert!(offline.iter().all(|mapping| mapping.state == "UNKNOWN"));
        assert_eq!(offline[1].source_node, server[1].source_node);
        assert_eq!(offline[1].target, server[1].target);

        config.storage_source_root = Some("/Users/Shared/storage".into());
        let outdated = node_nfs_mappings(&config, "login", Some(&health));
        assert!(outdated.iter().all(|mapping| mapping.state == "UNKNOWN"));
        health.execution_digest = config.execution_digest().unwrap();
        health.shares.clear();
        let refreshed = node_nfs_mappings(&config, "login", Some(&health));
        assert_eq!(refreshed[0].kind, "ALIAS");
        assert_eq!(refreshed[0].state, "READY");
        assert_eq!(refreshed[1].state, "UNKNOWN");
        health.execution_uid = 0;
        assert!(
            node_nfs_mappings(&config, "login", Some(&health))
                .iter()
                .all(|mapping| mapping.state == "UNKNOWN")
        );
    }

    #[test]
    fn storage_mapping_uses_the_provider_state_when_a_client_report_is_stale() {
        let ready = nfs_mapping(
            "login",
            "primary",
            "login",
            Path::new("/Users/Shared/macluster"),
            Path::new("/Users/Shared/macluster"),
            StorageProtocol::Nfs,
            "READY",
        );
        let stale = nfs_mapping(
            "worker",
            "primary",
            "login",
            Path::new("/Users/Shared/macluster"),
            Path::new("/Users/Shared/macluster"),
            StorageProtocol::Nfs,
            "UNKNOWN",
        );
        let row = |id: &str, mapping: NodeNfsMapping| NodeListRow {
            columns: [
                id.into(),
                "192.0.2.1".into(),
                "-".into(),
                "22".into(),
                "-".into(),
                "-".into(),
                "READY".into(),
            ],
            mappings: vec![mapping],
            storage: NodeStorageInventory::default(),
        };

        let mappings = aggregate_nfs_mappings(&[row("login", ready), row("worker", stale)]);
        assert_eq!(mappings.len(), 1);
        assert_eq!(
            mappings[0].state, "READY",
            "the storage provider's authenticated health must not be overridden by a stale client"
        );
    }

    #[test]
    fn node_list_refreshes_stale_health_before_rendering_mapping_state() {
        let config = parse_build_test_config();
        let root = test_exports_path();
        fs::create_dir_all(&root).unwrap();
        let sampled_unix_ms = 1_000_000_u64;
        let fresh = NodeHealth {
            machine_uuid: config.nodes["login"].machine_uuid.clone().unwrap(),
            execution_uid: 501,
            build_id: Some("older-agent-build".into()),
            logical_cpus: Some(8),
            execution_digest: config.execution_digest().unwrap(),
            primary_share_ready: true,
            ..Default::default()
        };
        let stale = NodeHealth {
            build_id: Some("older-agent-build".into()),
            ..fresh.clone()
        };
        let liveness = BTreeMap::from([(
            "login".to_owned(),
            macluster_controller::liveness::NodeLiveness {
                identity_key: config.nodes["login"]
                    .machine_uuid
                    .clone()
                    .unwrap()
                    .to_ascii_lowercase(),
                last_transition_unix_ms: sampled_unix_ms
                    .saturating_sub(super::NODE_LIST_HEALTH_CACHE_TTL_MS + 1),
                last_reachable_unix_ms: Some(sampled_unix_ms),
                health: Some(stale),
                health_sampled_unix_ms: Some(
                    sampled_unix_ms.saturating_sub(super::NODE_LIST_HEALTH_CACHE_TTL_MS + 1),
                ),
                agent_responding: Some(true),
                agent_sampled_unix_ms: Some(sampled_unix_ms),
                ..Default::default()
            },
        )]);
        let reachable = BTreeMap::from([("login".to_owned(), Some(true))]);

        let refreshed = super::refresh_node_health_for_list_with(
            &config,
            &root,
            liveness,
            &reachable,
            sampled_unix_ms,
            |node_id, _| {
                assert_eq!(node_id, "login");
                Some(fresh.clone())
            },
        );
        let health = refreshed["login"].health.as_ref().unwrap();
        assert_eq!(
            node_nfs_mappings(&config, "login", Some(health))[0].state,
            "READY"
        );
        fs::remove_dir_all(root).unwrap();
    }

