    #[test]
    fn failed_operations_report_pending_smb_mount_cleanup() {
        let root = std::env::temp_dir().join(format!("macluster-pending-smb-{}", Id128::random()));
        fs::create_dir_all(&root).unwrap();
        let path = root.join("smb-cleanup.json");
        let node = NodeConfig {
            host: "192.0.2.20".into(),
            transport: Transport::Ssh,
            remote_binary: "/usr/local/bin/macluster".into(),
            ssh_user: Some("worker".into()),
            ssh_port: Some(22),
            ssh_identity_file: None,
            remote_config: None,
            machine_uuid: Some("01234567-89ab-cdef-0123-456789abcdef".into()),
            execution_uid: Some(501),
        };
        let share = ShareConfig {
            protocol: StorageProtocol::Smb,
            server: NodeId::new("nas").unwrap(),
            source_root: "/data".into(),
            mount_root: "/Users/Shared/nas-data".into(),
            share_uuid: "928e8976-c946-509d-9e62-a3ef787664b7".into(),
            allow_existing_contents: false,
            smb_user: Some("smb-user".into()),
        };
        let mut pending =
            macluster_core::smb_credential_cleanup::GlobalSmbCredentialCleanup::default();
        pending.remember_node(super::deferred_smb_mount_cleanup("worker", &node, &share));
        let entry = pending.nodes.get_mut("worker").unwrap();
        entry.attempts = 2;
        entry.next_retry_unix_ms = 15_000;
        entry.last_error_kind = Some(macluster_core::nfs_reconcile::SmbCleanupFailureKind::Busy);
        entry.last_error_summary = Some("mount busy".into());
        pending.save(&path).unwrap();

        let lines = super::pending_smb_cleanup_lines(&path, 10_000).unwrap();

        assert_eq!(
            lines,
            [
                "worker  SMB cleanup pending",
                "  share 928e8976-c946-509d-9e62-a3ef787664b7 -> /Users/Shared/nas-data",
                "  attempts 2; busy; next retry in 5s",
                "  force: mnode -umount 928e8976-c946-509d-9e62-a3ef787664b7 --force --yes",
                "  wait: mnode -umount 928e8976-c946-509d-9e62-a3ef787664b7 --wait"
            ]
        );
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn smb_cleanup_wait_succeeds_when_the_journal_entry_disappears() {
        let node = NodeConfig {
            host: "192.0.2.20".into(),
            transport: Transport::Ssh,
            remote_binary: "/usr/local/bin/macluster".into(),
            ssh_user: Some("worker".into()),
            ssh_port: Some(22),
            ssh_identity_file: None,
            remote_config: None,
            machine_uuid: Some("machine".into()),
            execution_uid: Some(501),
        };
        let share = ShareConfig {
            protocol: StorageProtocol::Smb,
            server: NodeId::new("nas").unwrap(),
            source_root: "/data".into(),
            mount_root: "/Users/Shared/data".into(),
            share_uuid: "928e8976-c946-509d-9e62-a3ef787664b7".into(),
            allow_existing_contents: false,
            smb_user: Some("smb-user".into()),
        };
        let mut pending =
            macluster_core::smb_credential_cleanup::GlobalSmbCredentialCleanup::default();
        pending.remember_node(super::deferred_smb_mount_cleanup("worker", &node, &share));
        let mut polls = 0;
        let mut now_ms = 0_u64;

        super::wait_for_smb_cleanup_with(
            &share.share_uuid,
            Duration::from_secs(10),
            Duration::from_secs(1),
            || {
                polls += 1;
                Ok(if polls == 1 {
                    pending.clone()
                } else {
                    macluster_core::smb_credential_cleanup::GlobalSmbCredentialCleanup::default()
                })
            },
            || {
                now_ms += 1_000;
                now_ms
            },
            |_| {},
            |_| {},
        )
        .unwrap();
        assert_eq!(polls, 2);
    }

    #[test]
    fn smb_cleanup_wait_runs_after_cluster_maintenance_is_released() {
        let root =
            std::env::temp_dir().join(format!("macluster-smb-wait-order-{}", Id128::random()));
        fs::create_dir_all(&root).unwrap();
        let config_path = root.join("config.toml");
        let state_dir = root.join("state");
        fs::write(
            &config_path,
            "[cluster]\nname = \"test\"\ndefault_queue = \"compute\"\nshared_root = \"/Users/Shared/macluster\"\nshare_uuid = \"00000000-0000-4000-8000-000000000001\"\nstorage_server = \"nas\"\nprotocol_version = 1\n\n[queues.compute]\nnodes = []\nscheduler = \"fifo\"\n\n[nodes.nas]\nhost = \"192.0.2.5\"\ntransport = \"storage\"\n\n[shares.smb]\nprotocol = \"smb\"\nserver = \"nas\"\nsource_root = \"/Partition_2\"\nmount_root = \"/Users/Shared/smb\"\nshare_uuid = \"00000000-0000-4000-8000-000000000002\"\nsmb_user = \"guest\"\n",
        )
        .unwrap();
        Storage::open(&state_dir).unwrap();
        let barrier = macluster_core::maintenance::maintenance_barrier_path(&config_path);
        let observed = Arc::new(Mutex::new(None));
        let observed_by_wait = Arc::clone(&observed);

        super::unregister_smb_share_with_cleanup_wait(
            &config_path,
            &state_dir,
            "smb",
            Path::new("/Users/Shared/smb"),
            false,
            false,
            true,
            Some(1),
            move |share_uuid, timeout| {
                *observed_by_wait.lock().unwrap() =
                    Some((share_uuid.to_owned(), timeout, barrier.exists()));
                Ok(())
            },
        )
        .unwrap();

        assert_eq!(
            observed.lock().unwrap().clone(),
            Some((
                "00000000-0000-4000-8000-000000000002".to_owned(),
                Duration::from_secs(1),
                false,
            ))
        );
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn forcing_one_pending_cleanup_share_preserves_other_shares() {
        let node = NodeConfig {
            host: "192.0.2.20".into(),
            transport: Transport::Ssh,
            remote_binary: "/usr/local/bin/macluster".into(),
            ssh_user: Some("worker".into()),
            ssh_port: Some(22),
            ssh_identity_file: None,
            remote_config: None,
            machine_uuid: Some("01234567-89ab-cdef-0123-456789abcdef".into()),
            execution_uid: Some(501),
        };
        let share = |name: &str, uuid: &str| ShareConfig {
            protocol: StorageProtocol::Smb,
            server: NodeId::new("nas").unwrap(),
            source_root: format!("/{name}").into(),
            mount_root: format!("/Users/Shared/{name}").into(),
            share_uuid: uuid.into(),
            smb_user: Some("worker".into()),
            allow_existing_contents: false,
        };
        let forced = share("busy", "b483b6fb-a355-55c6-bf1c-d4f7a4fe9618");
        let remaining = share("remaining", "e6fe7c50-8ea9-567c-9238-e7fe1799fbf3");
        let mut journal =
            macluster_core::smb_credential_cleanup::GlobalSmbCredentialCleanup::default();
        journal.remember_node(
            macluster_core::nfs_reconcile::DeferredSmbCredentialCleanup {
                node_id: "worker".into(),
                machine_uuid: node.machine_uuid.clone(),
                node: node.clone(),
                shares: vec![forced.clone(), remaining.clone()],
                endpoints: Vec::new(),
                wait_for_unmount: true,
                attempts: 90,
                next_retry_unix_ms: 10_000,
                last_error_kind: Some(macluster_core::nfs_reconcile::SmbCleanupFailureKind::Busy),
                last_error_summary: Some("operation remained busy".into()),
            },
        );
        let mut calls = Vec::new();

        let outcome = force_pending_smb_share_with(
            &mut journal,
            &forced.share_uuid,
            20_000,
            |candidate, selected| {
                calls.push((candidate.host.clone(), selected.share_uuid.clone()));
                Ok(())
            },
        );

        assert_eq!(calls, [("192.0.2.20".into(), forced.share_uuid.clone())]);
        assert_eq!(outcome.forced_nodes, ["worker"]);
        assert!(outcome.failures.is_empty());
        assert_eq!(journal.nodes["worker"].shares, [remaining]);
        assert_eq!(journal.nodes["worker"].next_retry_unix_ms, 0);
    }

