    #[test]
    fn controller_migration_smb_credential_b_import_verify_and_cleanup_order() {
        let provisions = [
            smb_test_provision(1),
            smb_test_provision_for_server(2, "nas-02"),
        ];
        let events = Arc::new(Mutex::new(Vec::new()));
        super::stage_target_smb_masters(
            &provisions,
            {
                let events = Arc::clone(&events);
                move |provision| {
                    events
                        .lock()
                        .unwrap()
                        .push(format!("import:{}", provision.key.server_id));
                    Ok(())
                }
            },
            {
                let events = Arc::clone(&events);
                move |provision| {
                    events
                        .lock()
                        .unwrap()
                        .push(format!("verify:{}", provision.key.server_id));
                    Ok(())
                }
            },
            |_| {},
        )
        .unwrap();
        events.lock().unwrap().push("fence".into());
        assert_eq!(
            events.lock().unwrap().as_slice(),
            [
                "import:nas-01",
                "import:nas-02",
                "verify:nas-01",
                "verify:nas-02",
                "fence"
            ]
        );
    }

    #[test]
    fn controller_migration_smb_credential_import_failure_cleans_only_imported_items() {
        let provisions = [
            smb_test_provision(1),
            smb_test_provision_for_server(2, "nas-02"),
        ];
        let events = Arc::new(Mutex::new(Vec::new()));
        let error = super::stage_target_smb_masters(
            &provisions,
            {
                let events = Arc::clone(&events);
                move |provision| {
                    events
                        .lock()
                        .unwrap()
                        .push(format!("import:{}", provision.key.server_id));
                    if provision.key.server_id.as_str() == "nas-02" {
                        Err("target helper unavailable".into())
                    } else {
                        Ok(())
                    }
                }
            },
            |_| panic!("verification must not run after import failure"),
            {
                let events = Arc::clone(&events);
                move |provision| {
                    events
                        .lock()
                        .unwrap()
                        .push(format!("cleanup:{}", provision.key.server_id));
                }
            },
        )
        .unwrap_err();
        assert!(error.contains("unavailable"));
        assert_eq!(
            events.lock().unwrap().as_slice(),
            [
                "import:nas-01",
                "import:nas-02",
                "cleanup:nas-02",
                "cleanup:nas-01"
            ]
        );
    }

    #[test]
    fn controller_migration_smb_credential_preactivation_failure_cleans_all_staged_targets() {
        let provisions = [
            smb_test_provision(1),
            smb_test_provision_for_server(2, "nas-02"),
        ];
        let cleaned = Arc::new(Mutex::new(Vec::new()));
        super::cleanup_target_smb_masters_with(&provisions, {
            let cleaned = Arc::clone(&cleaned);
            move |provision| {
                cleaned
                    .lock()
                    .unwrap()
                    .push(provision.key.server_id.to_string());
            }
        });

        assert_eq!(cleaned.lock().unwrap().as_slice(), ["nas-01", "nas-02"]);
    }

