    #[test]
    fn node_listing_uses_one_successful_health_request() {
        let root = test_exports_path();
        fs::create_dir_all(&root).unwrap();
        let binary = root.join("macluster");
        let log = root.join("calls");
        let health = NodeHealth {
            machine_uuid: "01234567-89ab-cdef-0123-456789abcdef".into(),
            execution_uid: 501,
            build_id: Some(macluster_protocol::BUILD_ID.to_owned()),
            logical_cpus: None,
            execution_digest: "test-digest".into(),
            primary_share_ready: true,
            shares: BTreeMap::new(),
            features: Vec::new(),
            ..Default::default()
        };
        let encoded_health =
            serde_json::to_string(&serde_json::to_string(&health).unwrap()).unwrap();
        let log_path = serde_json::to_string(log.to_str().unwrap()).unwrap();
        fs::write(&binary, format!(
            "#!/usr/bin/env python3\nimport json,struct,sys\nwith open({log_path},'a') as f: f.write('call\\n')\nif 'agent-stdio' not in sys.argv: sys.exit(77)\nn=struct.unpack('>I',sys.stdin.buffer.read(4))[0]\nr=json.loads(sys.stdin.buffer.read(n))\nh=json.loads({encoded_health})\np=json.dumps({{'protocol_version':r['protocol_version'],'request_id':r['request_id'],'result':{{'Ok':{{'type':'health','payload':h}}}}}}).encode()\nsys.stdout.buffer.write(struct.pack('>I',len(p))+p)\n"
        )).unwrap();
        fs::set_permissions(&binary, fs::Permissions::from_mode(0o755)).unwrap();
        let mut node = parse_build_test_config().nodes["login"].clone();
        node.transport = Transport::Local;
        node.remote_binary = binary.to_string_lossy().into_owned();
        let (observed, online) =
            super::probe_node_list(&root.join("config.toml"), "test", "login", &node);
        assert_eq!(observed, Some(health));
        assert!(online);
        assert_eq!(fs::read_to_string(&log).unwrap(), "call\n");
        fs::write(
            &binary,
            format!(
                "#!/bin/sh\nprintf 'call\\n' >> {}\nexit 1\n",
                super::shell_quote(log.to_str().unwrap())
            ),
        )
        .unwrap();
        let (observed, online) =
            super::probe_node_list(&root.join("config.toml"), "test", "login", &node);
        assert!(observed.is_none());
        assert!(!online);
        assert_eq!(fs::read_to_string(&log).unwrap(), "call\ncall\n");
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn node_listing_bounds_health_and_ping_when_the_agent_stalls() {
        let root = test_exports_path();
        fs::create_dir_all(&root).unwrap();
        let binary = root.join("macluster");
        fs::write(&binary, "#!/bin/sh\nexec /bin/sleep 30\n").unwrap();
        fs::set_permissions(&binary, fs::Permissions::from_mode(0o755)).unwrap();
        let mut node = parse_build_test_config().nodes["login"].clone();
        node.transport = Transport::Local;
        node.remote_binary = binary.to_string_lossy().into_owned();

        let started = std::time::Instant::now();
        let (health, online) =
            super::probe_node_list(&root.join("config.toml"), "test", "login", &node);

        assert!(health.is_none());
        assert!(!online);
        assert!(
            started.elapsed() < Duration::from_secs(6),
            "stalled node listing probe took {:?}",
            started.elapsed()
        );
        fs::remove_dir_all(root).unwrap();
    }

