    #[test]
    fn nfs_exports_permission_failure_can_fall_back_only_in_local_terminal() {
        let mut local = local_share_test_node();
        local.host = "192.0.2.1".into();
        let mut remote = local.clone();
        remote.host = "192.0.2.2".into();
        remote.transport = Transport::Ssh;

        assert!(super::should_fallback_nfs_exports_to_terminal(
            &local,
            "NFS admin command failed: /bin/sh: /etc/exports: Operation not permitted",
            true,
        ));
        assert!(!super::should_fallback_nfs_exports_to_terminal(
            &local,
            "nfsd checkexports failed",
            true,
        ));
        assert!(!super::should_fallback_nfs_exports_to_terminal(
            &local,
            "/etc/exports: Operation not permitted",
            false,
        ));
        assert!(!super::should_fallback_nfs_exports_to_terminal(
            &remote,
            "/etc/exports: Operation not permitted",
            true,
        ));
    }

    #[test]
    fn remote_nfs_exports_permission_error_explains_the_per_node_privacy_gate() {
        let mut remote = local_share_test_node();
        remote.host = "192.0.2.3".into();
        remote.transport = Transport::Ssh;

        let guidance = super::nfs_exports_permission_failure_guidance(
            &remote,
            "NFS admin command failed: /bin/sh: line 34: /etc/exports: Operation not permitted",
        )
        .unwrap();

        assert!(guidance.contains("192.0.2.3"));
        assert!(guidance.contains("Full Disk Access"));
        assert!(guidance.contains("org.macluster.macluster"));
        assert!(guidance.contains("retry the command that triggered this authorization"));
        assert!(guidance.contains("transaction files were preserved"));
    }

